"VALIDACAO","REVISAO","ESPERANDO_FUNDADOR","EM_RESOLUCAO"],"situacao":"TRABALHO"},{"estado":"APROVADA","semaforo":"NAO_PODE","situacao":"APROVADA_NAO_PODE"},{"estado":"APROVADA","situacao":"APROVADA"},{"estado":"PRONTA","situacao":"PRONTA"},{"estado":"CANCELADA","fim":"PAI","situacao":"FIM_PAI"},{"estado":"CANCELADA","fim":"SUBSTITUIDO","situacao":"FIM_PAI"},{"estado":"CANCELADA","situacao":"FALHOU"},{"estado":"ENCERRADA_COM_FALHA","fim":"PULADA","situacao":"PULADA"},{"estado":"ENCERRADA_COM_FALHA","situacao":"ENCERROU"}],"tetos":{"TETO_AVISO_ESPERA":{"por_que":"Esperando capacidade: um aviso em 1 hora; em 6 horas você escolhe.","valor":1},"TETO_CHAMADAS":{"por_que":"Limite de chamadas: mais chamadas uma vez; na segunda, em resolução.","valor":1},"TETO_EXECUCOES":{"por_que":"Regra 5 e ''Teto geral'': cada etapa roda no máximo 6 vezes, somando autor e revisor, por qualquer motivo. As suas ordens abrem rodada nova e não gastam esse limite.","valor":6},"TETO_EXECUCOES_ACAO":{"por_que":"Regra 8: uma ação externa é executada no máximo uma vez, só pelo motor.","valor":1},"TETO_FALHAS_HELENA":{"por_que":"Se a leitura de volta da Helena falhar duas vezes, o card vai para você sem ela.","valor":2},"TETO_FORMATO":{"por_que":"Formato errado ganha UMA nova tentativa só de formato; na segunda, em resolução (K-13, A-17).","valor":1},"TETO_INFRA":{"por_que":"Regra 12: falha de provedor/servidor não gasta tentativa, mas na 3ª da mesma rodada a etapa para e chama você (plano: ''3ª queda da mesma etapa'').","valor":3},"TETO_LEMBRETES":{"por_que":"Espera interna por você: lembrete em 24h e 48h; depois, o padrão (que nunca aprova).","valor":2},"TETO_MUDANCAS_PRAZO":{"por_que":"Cada mudança de prazo sua rearma os 3 avisos do prazo novo. O teto deixa a prova terminar; na 4ª, o campo muda e os avisos ficam como estão (reação). PROPOSTA: depende do seu sim.","valor":3},"TETO_NIVEL_PRAZO":{"por_que":"Três níveis de prazo do card, cada um dispara uma vez: 80%, vencido, mais 1 hora.","valor":3},"TETO_ORDENS":{"por_que":"Suas ordens que reabrem trabalho no mesmo card (pedir ajuste, refazer, esperar, modelo menor, decisão nova, confirmar de novo depois de o validador do plano falhar). Não gastam o teto de 6, mas têm teto próprio para o card terminar e a prova acabar (MEL-23). Na 4ª, a ordem é LINHA, não comentário: este card é substituído por um card novo ligado, com as entregas deste e o seu pedido (E96, E97, E98, E117, C17, C29, C33): você nunca perde o poder de pedir e o card nunca fecha com a peça que você marcou como errada. PROPOSTA: depende do seu sim.","valor":3},"TETO_PERGUNTAS":{"por_que":"Limite de perguntas do card (plano l. 84 e 302). Número proposto, a calibrar na fase 3.","valor":2},"TETO_REPLANEJAMENTO":{"por_que":"Em resolução, ''refazer'' vale uma vez por etapa (plano: a etapa é replanejada uma vez).","valor":1},"TETO_REPROVACOES":{"por_que":"Duas voltas ao autor por reprovação; a reprovação seguinte vai para em resolução. Cabe exatamente no teto de 6.","valor":2},"TETO_TEMPO":{"por_que":"Tempo esgotado: mais uma tentativa com 50% mais tempo; na segunda, em resolução (divisão no meio desligada, MEL-24).","valor":1},"TETO_VALIDACAO_PLANO":{"por_que":"O validador do plano é código nosso e roda na hora: se não responder em 60 s, roda de novo uma vez; na 2ª, o card espera você com o motivo VALIDADOR_FALHOU.","valor":2},"TETO_VOLTAS_JURIDICO":{"por_que":"A etapa jurídica manda a peça julgada de volta no máximo 2 vezes; depois, em resolução (MEL-23 pede um teto só: 2, como no plano).","valor":2}},"variaveis":{"acao_externa":{"fim":{"dominio":["NENHUM","PAI","PADRAO","FUNDADOR","FALHA"],"inicial":"NENHUM"},"lembretes":{"inicial":0,"teto":"TETO_LEMBRETES"},"ok_registrado":{"inicial":0,"teto":1},"tentativas":{"inicial":0,"teto":"TETO_EXECUCOES_ACAO"}},"card":{"falhas_helena":{"inicial":0,"teto":"TETO_FALHAS_HELENA"},"fim":{"dominio":["NENHUM","PAI","PADRAO","PULADA","ENCERRAR_CARD","CARD_PRONTO","FUNDADOR","SUBSTITUIDO","FALHA"],"inicial":"NENHUM"},"lembretes":{"inicial":0,"teto":"TETO_LEMBRETES"},"motivo":{"dominio":["NENHUM","HELENA_FALHOU","PLANO_INVALIDO","VALIDADOR_FALHOU","DEPENDENCIA","NAO_PODE"],"inicial":"NENHUM"},"mudancas_prazo":{"inicial":0,"teto":"TETO_MUDANCAS_PRAZO"},"nivel_prazo":{"inicial":0,"teto":"TETO_NIVEL_PRAZO"},"ordens":{"compartilhada":true,"inicial":0,"teto":"TETO_ORDENS"},"perguntas":{"compartilhada":true,"inicial":0,"teto":"TETO_PERGUNTAS"},"validacoes":{"inicial":0,"teto":"TETO_VALIDACAO_PLANO"},"voltas":{"compartilhada":true,"inicial":0,"teto":"TETO_VOLTAS_JURIDICO"}},"etapa":{"aviso":{"inicial":0,"teto":"TETO_AVISO_ESPERA"},"chamadas":{"inicial":0,"teto":"TETO_CHAMADAS"},"espera":{"dominio":["NENHUMA","INTERNA","EXTERNA"],"inicial":"NENHUMA"},"exec_viva":{"inicial":0,"teto":1},"execucoes":{"inicial":0,"teto":"TETO_EXECUCOES"},"fim":{"dominio":["NENHUM","PAI","PADRAO","PULADA","ENCERRAR_CARD","CARD_PRONTO","FUNDADOR","SUBSTITUIDO","FALHA"],"inicial":"NENHUM"},"formato":{"inicial":0,"teto":"TETO_FORMATO"},"infra":{"inicial":0,"teto":"TETO_INFRA"},"lembretes":{"inicial":0,"teto":"TETO_LEMBRETES"},"leu_internet":{"inicial":0,"teto":1},"motivo":{"dominio":["NENHUM","NORMAL","CAPACIDADE","PERGUNTA","REVISAO","RESOLUCAO","INFRA"],"inicial":"NENHUM"},"ordens":{"compartilhada":true,"inicial":0,"teto":"TETO_ORDENS"},"perguntas":{"compartilhada":true,"inicial":0,"teto":"TETO_PERGUNTAS"},"replan":{"inicial":0,"teto":"TETO_REPLANEJAMENTO"},"reprovacoes":{"inicial":0,"teto":"TETO_REPROVACOES"},"revisor":{"dominio":["NENHUM"],"inicial":"NENHUM","mais":"revisores_possiveis"},"semaforo":{"dominio":["NENHUM","OK","AJUSTE","NAO_PODE"],"inicial":"NENHUM"},"tempo":{"inicial":0,"teto":"TETO_TEMPO"},"voltas":{"compartilhada":true,"inicial":0,"teto":"TETO_VOLTAS_JURIDICO"}}},"versao":"2.0.0"},"helena-v2/maquina/vocabulario.yaml":{"acoes":{"AUTOR":{"DEVOLVER_A_QUEM_PEDIU":{"efeito":"interno","parametros":{"usou_internet":["NAO","SIM"]},"preenchidos_pelo_motor":["usou_internet"]},"ENTREGAR":{"efeito":"interno","parametros":{"acao_externa":["NENHUMA","SO_FUNDADOR","PELO_MOTOR"],"parecer":["OK","AJUSTE","NAO_PODE"],"usou_internet":["NAO","SIM"]},"preenchidos_pelo_motor":["usou_internet"]},"PEDIR_SUBCARD":{"desligado":"v2.0 (MEL-24): sem sub-card até a fase 4; se chegar, conta como FORMATO_ERRADO","efeito":"interno","parametros":{"usou_internet":["NAO","SIM"]},"preenchidos_pelo_motor":["usou_internet"]},"PERGUNTAR":{"efeito":"interno","nota":"O tipo da espera (interna ou externa) não é parâmetro do agente: o código decide pelo roteiro.","parametros":{"usou_internet":["NAO","SIM"]},"preenchidos_pelo_motor":["usou_internet"]},"REGISTRAR_FALHA":{"efeito":"interno","parametros":{"motivo_falha":["NAO_CONSIGO","FALTAM_DADOS","FONTE_INSUFICIENTE"],"usou_internet":["NAO","SIM"]},"preenchidos_pelo_motor":["usou_internet"]}},"FUNDADOR":{"APROVAR":{"efeito":"interno","parametros":{}},"CANCELAR":{"efeito":"interno","parametros":{}},"MUDAR_PRAZO":{"efeito":"interno","muda_campo":"prazo","parametros":{}},"MUDAR_PRIORIDADE":{"efeito":"interno","muda_campo":"prioridade","parametros":{}},"PAUSAR_TUDO":{"efeito":"interno","parametros":{}},"PEDIR_AJUSTE":{"efeito":"interno","nota":"Na etapa, refaz a peça. No card aberto, é ajuste global da decisão: o sinal registrado refaz as etapas que a usaram. No card fechado, abre card ligado.","parametros":{"motivo_ajuste":["ERRO_DE_FATO","FALTOU_TEMA","TOM","FORMATO"]}},"RESPONDER":{"efeito":"interno","parametros":{"opcao":["RESPOSTA_A","RESPOSTA_B","RESPOSTA_C","CONFIRMO","REFAZER","SEGUIR_SEM","ENCERRAR","PULAR","ESPERAR","MODELO_MENOR","ACONTECEU","NAO_ACONTECEU","FEITO_POR_MIM"]}},"USAR_COMO_EXEMPLO":{"efeito":"interno","parametros":{}}},"HELENA":{"LER_DE_VOLTA":{"efeito":"interno","parametros":{}},"RECOMENDAR":{"efeito":"interno","parametros":{"opcao":["REFAZER","SEGUIR_SEM","ENCERRAR"]}},"SUGERIR_PRAZO":{"efeito":"interno","nota":"Vira item na lista do fundador; o prazo só muda pelo botão dele (regra 7).","parametros":{}}},"MOTOR":{"ACAO_CONCLUIDA":{"efeito":"interno","parametros":{}},"ACAO_FALHOU":{"efeito":"interno","parametros":{}},"AJUSTE_DO_JULGADOR":{"efeito":"interno","parametros":{}},"CANCELADO_PAI":{"efeito":"interno","parametros":{}},"CAPACIDADE_VOLTOU":{"efeito":"interno","parametros":{}},"CARD_PRONTO":{"efeito":"interno","parametros":{}},"DECISAO_MUDOU":{"efeito":"interno","parametros":{}},"DEPENDENCIAS_PRONTAS":{"efeito":"interno","parametros":{}},"DEPENDENCIA_MUDOU":{"efeito":"interno","parametros":{}},"ENCERRAR_CARD":{"efeito":"interno","parametros":{}},"EXECUTAR_ACAO":{"efeito":"externo","nota":"Único evento com efeito externo. Só o MOTOR, só depois do ok registrado, no máximo uma vez.","parametros":{}},"FALHA":{"efeito":"interno","parametros":{"classe":["FORMATO_ERRADO","LIMITE_CHAMADAS","GRANDE_DEMAIS","SITE","DESCONHECIDA"]}},"FALHA_INFRA":{"efeito":"interno","parametros":{"classe":["COTA","LOGIN","PROVEDOR","QUEDA","BANCO","FERRAMENTA"]}},"INICIAR_EXECUCAO":{"efeito":"interno","parametros":{}},"INICIAR_REVISAO":{"efeito":"interno","parametros":{}},"MOTIVO_RESOLVIDO":{"efeito":"interno","nota":"A pergunta do card perdeu o objeto (a etapa que a causou foi reaberta ou refeita): o card volta a andar sem gastar ordem sua.","parametros":{}},"PERGUNTAR_AO_FUNDADOR":{"efeito":"interno","parametros":{}},"PLANO_INVALIDO":{"efeito":"interno","parametros":{}},"PLANO_VALIDO":{"efeito":"interno","parametros":{}},"PORTAO1_OK":{"efeito":"interno","parametros":{"escolhido":"revisores_possiveis"}},"PORTAO1_RECUSOU":{"efeito":"interno","parametros":{}},"REABRIR_POR_ORDEM":{"efeito":"interno","parametros":{}},"SEM_CAPACIDADE":{"efeito":"interno","parametros":{"classe":["COTA","LOGIN","BANCO","AGENTE_PAUSADO"]}},"SUBSTITUIR_CARD":{"efeito":"interno","nota":"Ordem sua acima do teto de ordens numa etapa: o card é substituído por um card novo ligado, com as entregas e o seu pedido.","parametros":{}},"TETO_EXECUCOES":{"efeito":"interno","parametros":{}},"TODAS_PRONTAS":{"efeito":"interno","parametros":{}}},"RELOGIO":{"AVISO_1H":{"efeito":"interno","parametros":{}},"ESPERA_6H":{"efeito":"interno","parametros":{}},"LEMBRETE_24H":{"efeito":"interno","parametros":{}},"LEMBRETE_48H":{"efeito":"interno","parametros":{}},"PRAZO_80":{"efeito":"interno","parametros":{}},"PRAZO_ESPERA_VENCIDO":{"efeito":"interno","parametros":{}},"PRAZO_MAIS_1H":{"efeito":"interno","parametros":{}},"PRAZO_VENCIDO":{"efeito":"interno","parametros":{}},"TEMPO_ESGOTADO":{"efeito":"interno","parametros":{}}},"REVISOR":{"APROVAR":{"efeito":"interno","nota":"Resumo calculado pelo código a partir dos critérios (MEL-29): todos APROVADO, ou só NAO_CONSIGO_CONFERIR de risco baixo, que fica marcado ''sem conferir'' na faixa.","parametros":{}},"NAO_CONSIGO_CONFERIR":{"efeito":"interno","nota":"Critério de risco alto fora do alcance do revisor: vira cartão de revisão para você, com texto montado pelo código.","parametros":{}},"REPROVAR":{"efeito":"interno","nota":"Algum critério REPROVADO, ou NAO_CONSIGO_CONFERIR por falta de prova na entrega (defeito do autor).","parametros":{}}},"VIGIA":{"REGRA_QUEBRADA":{"efeito":"interno","parametros":{}},"SEM_EXECUCAO_VIVA":{"efeito":"interno","parametros":{}}}},"botoes_do_fundador":["APROVAR","PEDIR_AJUSTE","USAR_COMO_EXEMPLO","CANCELAR","RESPONDER","PAUSAR_TUDO","MUDAR_PRIORIDADE","MUDAR_PRAZO"],"classes_de_falha":{"ACAO_EXTERNA":{"evento":["ENTREGAR"],"gasta_tentativa":false,"resposta":"vai para a lista do que só você faz; nunca é executada pelo agente"},"BANCO":{"evento":["FALHA_INFRA","SEM_CAPACIDADE"],"gasta_tentativa":false,"resposta":"pausa a fila; aviso direto, sem passar pelo banco"},"COTA":{"evento":["FALHA_INFRA","SEM_CAPACIDADE"],"gasta_tentativa":false,"resposta":"fila com motivo CAPACIDADE e hora de voltar; aviso em 1h; em 6h você escolhe"},"DESCONHECIDA":{"evento":["FALHA"],"gasta_tentativa":true,"resposta":"para só a etapa, guarda tudo, aviso na hora; em resolução"},"FERRAMENTA":{"evento":["FALHA_INFRA"],"gasta_tentativa":false,"resposta":"execução não conta e é refeita"},"FORMATO_ERRADO":{"evento":["FALHA"],"gasta_tentativa":true,"resposta":"uma nova tentativa só de formato; na segunda, em resolução"},"GRANDE_DEMAIS":{"evento":["FALHA"],"gasta_tentativa":true,"resposta":"em resolução; divisão só a declarada no roteiro (MEL-24)"},"LIMITE_CHAMADAS":{"evento":["FALHA"],"gasta_tentativa":true,"resposta":"mais chamadas uma vez; na segunda, em resolução"},"LOGIN":{"evento":["FALHA_INFRA","SEM_CAPACIDADE"],"gasta_tentativa":false,"resposta":"pausa sem perder etapa; aviso na hora com o passo a passo"},"PROVEDOR":{"evento":["FALHA_INFRA"],"gasta_tentativa":false,"resposta":"refaz sem gastar tentativa"},"QUEDA":{"evento":["FALHA_INFRA","SEM_EXECUCAO_VIVA"],"gasta_tentativa":false,"resposta":"retoma do último passo; resposta gravada é reusada"},"REPROVADO":{"evento":["REPROVAR"],"gasta_tentativa":true,"resposta":"volta ao autor com os critérios; depois de 2 voltas, em resolução"},"SITE":{"evento":["FALHA"],"gasta_tentativa":true,"resposta":"a ferramenta já tentou 3 vezes e trocou de fonte; sem alternativa, em resolução"},"TEMPO":{"evento":["TEMPO_ESGOTADO"],"gasta_tentativa":true,"resposta":"mais uma, com 50% mais tempo; na segunda, em resolução"}},"entradas_do_app":{"BOTAO":"Leva o número único do toque e a versão que você viu (regras_gerais.toques_do_fundador_exigem_versao_vista); com versão antiga, Aprovar, Pedir ajuste e Responder nunca mudam estado. Pedir ajuste no card aberto emite decisão nova com origem neste toque.","NOVO_PEDIDO":"O código grava a mensagem com o número único do app e cria o card em RASCUNHO, antes de qualquer IA.","TEXTO_NO_CARD":"Vira comentário do card e nunca muda estado."},"identidades":{"agentes":["HELENA","LAURA","AUGUSTO","MARINA","CAIO","CLARA","BIANCA","DANIEL","THEO","NINA","RAVI","MAYA","BRUNO","OLIVIA","VICTOR","CAMILA","ISABELA","PEDRO","RENATA","JOANA","FELIPE"],"fundador":"FUNDADOR"},"maquinas":{"acao_externa":{"abertos":["PROPOSTA","AUTORIZADA","EXECUTANDO_ACAO","INCERTA"],"finais":["EXECUTADA","FEITA_PELO_FUNDADOR","RECUSADA","EXPIRADA","FALHOU","NAO_CONFIRMADA","CANCELADA"]},"card":{"abertos":["RASCUNHO","ESPERANDO_CONFIRMACAO","VALIDANDO_PLANO","EM_ANDAMENTO","ESPERANDO_FUNDADOR"],"finais":["PRONTO","CANCELADO","ENCERRADO_COM_FALHA"]},"etapa":{"abertos":["AGUARDANDO_ANTERIORES","NA_FILA","EXECUTANDO","VALIDACAO","REVISAO","ESPERANDO_FUNDADOR","EM_RESOLUCAO","APROVADA"],"finais":["PRONTA","CANCELADA","ENCERRADA_COM_FALHA"]}},"motivos":{"espera_da_etapa":["PERGUNTA","REVISAO","RESOLUCAO","INFRA"],"espera_do_card":["HELENA_FALHOU","PLANO_INVALIDO","VALIDADOR_FALHOU","DEPENDENCIA","NAO_PODE"],"fila":["NORMAL","CAPACIDADE"],"fim":["PAI","PADRAO","PULADA","ENCERRAR_CARD","CARD_PRONTO","FUNDADOR","SUBSTITUIDO","FALHA","NENHUM"],"tipo_de_espera":["INTERNA","EXTERNA"]},"motivos_de_ajuste":["ERRO_DE_FATO","FALTOU_TEMA","TOM","FORMATO"],"motivos_do_agente":["NAO_CONSIGO","FALTAM_DADOS","FONTE_INSUFICIENTE"],"papeis":{"AUTOR":{"descricao":"Agente dono do serviço da etapa. Só escreve conteúdo e devolve UMA ação.","e_ia":true,"pode_agir_fora":false},"FUNDADOR":{"descricao":"Você. Botões do card no app; única fonte de prioridade, prazo e ok para ação externa.","e_ia":false,"pode_agir_fora":true},"HELENA":{"descricao":"AGT-01 como dona do card (leitura de volta, recomendação numa resolução). Quando a Helena escreve uma entrega ela é AUTOR; quando revisa, é REVISOR.","e_ia":true,"pode_agir_fora":false},"MOTOR":{"descricao":"Quem executa (fila, execuções, validação por código, sinais entre etapas). Só ele grava, pela função única do banco.","e_ia":false,"pode_agir_fora":true},"RELOGIO":{"descricao":"Relógio dos prazos, dentro do banco, horário de Brasília. Cada nível dispara uma vez.","e_ia":false,"pode_agir_fora":false},"REVISOR":{"descricao":"Agente designado pelo motor para conferir a entrega (nunca o autor nem quem julga a peça depois).","e_ia":true,"pode_agir_fora":false},"VIGIA":{"descricao":"Checagem a cada 5 minutos. Devolve à fila a execução sem processo vivo e acende a luz; nunca congela card.","e_ia":false,"pode_agir_fora":false}},"papeis_do_sistema":["MOTOR","RELOGIO","VIGIA"],"versao":"2.0.0"},"helena-v2/models.yaml":{"apelidos":{"analise-padrao":{"modelo":"gpt-6-sol","para_que":"Autor de contas, dados, estratégia, projetos, administração, produto, tecnologia, testes, prática pessoal e do relatório final.","provedor":"openai-codex"},"conteudo-padrao":{"modelo":"gpt-6-sol","para_que":"Autor de texto: convite, roteiro de treinamento, abordagem comercial, tese de parceria, plano de campanha, plano de sucesso, resposta a cliente, perfil de função e procedimento.","provedor":"openai-codex"},"coordenacao-padrao":{"modelo":"gpt-6.1-sol","para_que":"Só a coordenação da Helena: leitura de volta e recomendação. É o modelo de cota mais curta; nada mais roda nele.","provedor":"openai-codex"},"pesquisa-padrao":{"modelo":"gpt-6-sol","para_que":"Autor de serviço que lê páginas: parecer e dossiê.","provedor":"openai-codex"},"revisao-padrao":{"modelo":"gpt-6-sol","para_que":"Toda revisão, de qualquer agente, inclusive as da Helena e a do relatório final.","provedor":"openai-codex"}},"cota":{"cota_esgotada":"Falha de infraestrutura classe COTA: não gasta tentativa; a etapa fica na fila com motivo CAPACIDADE e a hora de voltar; aviso em 1 hora; em 6 horas você escolhe ESPERAR, MODELO_MENOR (só nas condições acima) ou cancelar.","orcamento_diario_v2":{"dia":"De 00:00 a 23:59, horário de Brasília.","parte_do_limite":"Uma parte fixa do limite do plano; o resto fica para a v1 enquanto ela rodar. Nunca o limite inteiro.","sem_valor":"O motor não liga em produção com valor nulo.","unidade":"execucoes_de_agente","valor":null},"ordem_quando_aperta":["HELENA_RECEBENDO_PEDIDOS","REVISOES","CARDS_EM_ANDAMENTO","CARDS_NOVOS","CASOS_DE_TESTE"],"se_o_teste_1_falhar":"Primeira saída: passar tarefas simples para o modelo menor, trocando o modelo de um apelido de AUTOR por PR neste arquivo, com os testes de troca e o seu toque (nunca a coordenação nem a revisão). Segunda: decisão sua entre o plano Pro e créditos avulsos. A DEC-014 continua valendo nos dois casos.","uso_medido_separado":"O uso da v1 e o da v2 são medidos separados (teste 1)."},"modelo_menor_por_ordem_sua":{"condicoes":["A espera é de cota (classe COTA). Login, provedor, queda, banco ou ferramenta: o cartão não oferece.","O serviço da etapa tem modelo_menor APTO em servicos.yaml: a bateria do serviço passou 3 de 3 com o modelo menor, com o seu toque.","Nunca no SRV-PARECER nem no SRV-RELATORIO-FINAL (modelo_menor NUNCA)."],"fora_das_condicoes":"O cartão não mostra a opção. Se ela chegar mesmo assim, o motor trata como ESPERAR (a máquina tem a mesma passagem para as duas, E88) e o card registra ''modelo menor recusado: fora das condições''.","hoje":"Nenhum serviço tem a bateria no modelo menor: na v2.0 o cartão de cota oferece só ESPERAR ou cancelar.","modelo":"gpt-6-luna","na_faixa_do_card":"A entrega mostra ''feita com o modelo menor, por sua escolha''.","provedor":"openai-codex","vale_para":"Só as execuções do AUTOR da etapa em que você respondeu MODELO_MENOR, até ela terminar. A revisão e a Helena rodam sempre no apelido delas. Nunca vira padrão do apelido."},"papel_do_apelido":{"analise-padrao":"AUTOR","conteudo-padrao":"AUTOR","coordenacao-padrao":"COORDENACAO","pesquisa-padrao":"AUTOR","revisao-padrao":"REVISAO"},"provedor":"openai-codex","regras":["Cada apelido tem exatamente: modelo, provedor e para_que. Campo ''reserva'', ''fallback'' ou segundo provedor é recusado.","Todo apelido usado numa ficha existe aqui e é usado só no papel dele (papel_do_apelido): modelo.revisao = revisao-padrao em toda ficha; modelo.coordenacao = coordenacao-padrao só na Helena; modelo.autor é um apelido de papel AUTOR.","Serviço com ferramenta de leitura (usa_internet) usa modelo.autor = pesquisa-padrao; os outros nunca usam pesquisa-padrao.","Um apelido apontando para modelo que não existe vira aviso, nunca troca escondida.","O motor confere, no registro de uso de cada execução, que o modelo e o provedor foram os do apelido; se não foram, a execução não conta e vira aviso (falha de infraestrutura, sem gastar tentativa).","O perfil de cada execução tem só o modelo do apelido; nenhuma lista de modelos alternativos."],"troca_de_modelo":{"exige":["60 casos simulados e 60 reais, e o placar de 20 casos rodado 3 vezes lado a lado.","Regressão 3 de 3 em cada caso de regressão; caso que passa a errar sempre bloqueia, mesmo com a média boa.","Nota conferida pelo código cai no máximo 5 pontos.","Troca do apelido revisao-padrao: o teste 9 de todos os pares com aptidão APTA roda de novo (MEL-41).","48 horas em observação depois de publicar."],"vigilancia_de_troca_escondida":"Toda noite, 5 casos fixos com conferência só por código; duas noites seguidas de falha geram aviso para você (o ChatGPT não diz qual modelo respondeu)."},"versao":"3.1.0"},"helena-v2/organograma.yaml":{"agentes":[{"cargo":"Coordenadora (CEO virtual)","escopo":"EMPRESAS","estado":"ESTAGIO","fase_de_ativacao":"v2.0","grupo":"GRP-COORDENACAO","id":"AGT-01","identidade":"HELENA","nome":"Helena"},{"cargo":"Comunicação e desenvolvimento do fundador","escopo":"PESSOAL","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-PESSOAL-DO-FUNDADOR","id":"AGT-02","identidade":"LAURA","nome":"Laura"},{"cargo":"Estratégia","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-ESTRATEGIA-PROJETOS","id":"AGT-03","identidade":"AUGUSTO","nome":"Augusto"},{"cargo":"Planos de projeto e cronogramas","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-ESTRATEGIA-PROJETOS","id":"AGT-04","identidade":"MARINA","nome":"Marina"},{"cargo":"Finanças","escopo":"EMPRESAS","estado":"ESTAGIO","fase_de_ativacao":"v2.0","grupo":"GRP-FINANCAS-DADOS-ADM","id":"AGT-05","identidade":"CAIO","nome":"Caio"},{"cargo":"Jurídico, risco e conformidade","escopo":"EMPRESAS","estado":"ESTAGIO","fase_de_ativacao":"v2.0","grupo":"GRP-JURIDICO-RISCO","id":"AGT-06","identidade":"CLARA","nome":"Clara"},{"cargo":"Pessoas e cultura","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-PESSOAS","id":"AGT-07","identidade":"BIANCA","nome":"Bianca"},{"cargo":"Dados e indicadores","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-FINANCAS-DADOS-ADM","id":"AGT-08","identidade":"DANIEL","nome":"Daniel"},{"cargo":"Tecnologia","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-PRODUTO-TECNOLOGIA","id":"AGT-09","identidade":"THEO","nome":"Theo"},{"cargo":"Produto","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-PRODUTO-TECNOLOGIA","id":"AGT-10","identidade":"NINA","nome":"Nina"},{"cargo":"Pesquisa","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 3","grupo":"GRP-MERCADO","id":"AGT-11","identidade":"RAVI","nome":"Ravi"},{"cargo":"Design de experiência e interface","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-PRODUTO-TECNOLOGIA","id":"AGT-12","identidade":"MAYA","nome":"Maya"},{"cargo":"Testes de produto e software","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-PRODUTO-TECNOLOGIA","id":"AGT-13","identidade":"BRUNO","nome":"Bruno"},{"cargo":"Operações (rotina interna)","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-CLIENTES-OPERACAO","id":"AGT-14","identidade":"OLIVIA","nome":"Olívia"},{"cargo":"Vendas","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-MERCADO","id":"AGT-15","identidade":"VICTOR","nome":"Victor"},{"cargo":"Marketing e crescimento","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-MERCADO","id":"AGT-16","identidade":"CAMILA","nome":"Camila"},{"cargo":"Conteúdo e texto","escopo":"EMPRESAS","estado":"ESTAGIO","fase_de_ativacao":"v2.0","grupo":"GRP-MERCADO","id":"AGT-17","identidade":"ISABELA","nome":"Isabela"},{"cargo":"Parcerias","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-MERCADO","id":"AGT-18","identidade":"PEDRO","nome":"Pedro"},{"cargo":"Sucesso do cliente","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-CLIENTES-OPERACAO","id":"AGT-19","identidade":"RENATA","nome":"Renata"},{"cargo":"Atendimento (rascunhos de resposta)","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-CLIENTES-OPERACAO","id":"AGT-20","identidade":"JOANA","nome":"Joana"},{"cargo":"Administração","escopo":"EMPRESAS","estado":"PAUSADO","fase_de_ativacao":"fase 4","grupo":"GRP-FINANCAS-DADOS-ADM","id":"AGT-21","identidade":"FELIPE","nome":"Felipe"}],"coordenacao":{"estados_separados":"Coordenação (ATIVA ou PAUSADA, só por toque seu), aptidões de revisão (por tipo) e o serviço de relatório (autor) são independentes: pausar o relatório não para a leitura de volta nem as revisões (servicos.yaml, MAT-13).","identidade":"HELENA","o_que_faz":"Leitura de volta (escolhe 1 serviço, 1 roteiro ou ''fora da v2''), recomendação numa etapa em resolução (lista fechada), relatório final, e revisão de cálculo, parecer e prática pessoal.","o_que_nao_faz":"Não escolhe empresa, fila, prioridade nem prazo; não replaneja; não executa trabalho de especialista; não é revisora universal; não recomenda sobre peça de que participou (servicos.yaml, MAT-26)."},"empresas":{"BIZ-001":{"area":"Energia solar e sustentabilidade; foco em validação e aquisição comercial.","nome":"iGreen Energy","pacote":{"dono":"FUNDADOR","estado":"NAO_CONFIRMADO","falta":"Voz e proibições (ex.: nenhuma promessa de economia garantida).","prazo":"Antes de qualquer serviço atender a iGreen; no mais tardar, no portão da fase 4 (servicos.yaml, FORA-PACOTE-DE-VOZ)."}},"BIZ-002":{"area":"Saúde, nutrição, longevidade e medicina preventiva.","nome":"Ecossistema de Saúde","pacote":{"dono":"FUNDADOR","estado":"NAO_CONFIRMADO","falta":"Voz e proibições (ex.: nenhuma promessa de cura, nenhum diagnóstico, regras de publicidade de saúde).","prazo":"Antes de qualquer serviço atender o Ecossistema de Saúde; no mais tardar, no portão da fase 4 (servicos.yaml, FORA-PACOTE-DE-VOZ)."}},"BIZ-003":{"area":"Conecta pessoas adultas a oportunidades de dados para inteligência artificial (Mimix e Hub). Primeira meta da v2.","nome":"Humano Digital","pacote":{"conteudo":"Decisões DEC-024 e DEC-025 (vigentes, lidas na hora pelo motor); proibido qualquer termo de ganho no convite (C-11).","estado":"CONFIRMADO"}},"BIZ-004":{"area":"Inteligência pessoal de evolução (nunca app fitness comum nem contador de calorias).","nome":"eLiving™","pacote":{"conteudo":"Grafia exata ''eLiving™'' (nunca ''E-living'', ''Eliving'' ou ''Iliving''); slogan ''Onde sua evolução ganha direção.''; quatro pilares do produto: Sirlene (Nutrição), Doutor Vital (Saúde), Alex (Movimento) e Rafael (Hábitos), com os limites deles (nenhum diagnóstico, prescrição, treino clínico ou promessa de cura). Fontes: docs/manual/eliving/comando-master-eliving.md e docs/manual/eliving/manual-de-comportamento-agentes-eliving.md (DEC-023).","estado":"CONFIRMADO"}}},"escopo_pessoal":{"codigo":"PESSOAL","quem_atende":["LAURA"],"regra":"Dados pessoais seus não se misturam com o contexto das empresas; a Laura não recebe pacote de empresa."},"fonte_dos_nomes":"maquina/vocabulario.yaml","fora_do_organograma":{"motor_relogio_vigia":"Peças de código (papéis MOTOR, RELOGIO e VIGIA da máquina), não agentes.","personagens_do_produto_eliving":{"o_que_sao":"Personagens do produto eLiving™ (Nutrição, Saúde, Movimento e Hábitos). Não são funcionários, não são agentes, não recebem card e não aparecem em servicos.yaml nem no vocabulário da máquina.","onde_ficam":"Numa pasta própria do produto. O prefixo de ID deles é decisão sua.","quem":["Sirlene","Doutor Vital","Alex","Rafael"]}},"fundador":{"identidade":"FUNDADOR","responsavel_por":"Todos os agentes e todas as empresas.","so_ele":["Empresa, prioridade e prazo de qualquer card (caixa Novo pedido e botões; regra 7).","Ok para qualquer ação externa: cadastro, contato, gasto, contrato ou publicação (regra 8), uma vez.","Segundo revisor de todo parecer jurídico (''leia antes de agir'').","Subir um serviço de estado (estágio, ativo), ligar a aptidão de revisão de cada par e publicar.","Pausar ou religar a coordenação da Helena e as aptidões de revisão (o disjuntor só pausa serviço).","Escrever o pacote de voz e proibições de cada empresa (servicos.yaml, FORA-PACOTE-DE-VOZ).","Última reserva de toda revisão: se ninguém mais puder revisar, a revisão vem para ele."]},"grupos":{"GRP-CLIENTES-OPERACAO":{"agentes":["RENATA","JOANA","OLIVIA"],"nome":"Clientes e operação"},"GRP-COORDENACAO":{"agentes":["HELENA"],"nome":"Coordenação"},"GRP-ESTRATEGIA-PROJETOS":{"agentes":["AUGUSTO","MARINA"],"nome":"Estratégia e projetos"},"GRP-FINANCAS-DADOS-ADM":{"agentes":["CAIO","DANIEL","FELIPE"],"nome":"Finanças, dados e administração"},"GRP-JURIDICO-RISCO":{"agentes":["CLARA"],"nome":"Jurídico e risco"},"GRP-MERCADO":{"agentes":["RAVI","CAMILA","ISABELA","VICTOR","PEDRO"],"nome":"Mercado e crescimento"},"GRP-PESSOAL-DO-FUNDADOR":{"agentes":["LAURA"],"nome":"Pessoal do fundador"},"GRP-PESSOAS":{"agentes":["BIANCA"],"nome":"Pessoas"},"GRP-PRODUTO-TECNOLOGIA":{"agentes":["NINA","MAYA","THEO","BRUNO"],"nome":"Produto e tecnologia"}},"sobreposicoes_resolvidas":[{"como":"O motor coordena cards e etapas (fila, dependências, prazos, avisos). A Marina escreve planos de projeto e cronogramas para VOCÊ executar fora do sistema; nunca acompanha, move ou cobra card.","entre":"Marina e o motor"},{"como":"Cada serviço tem o seu revisor na matriz. O Bruno testa produto e software (plano e leitura de testes) e é só reserva de dois tipos de produto; não é revisor universal.","entre":"Bruno e os revisores"},{"como":"Olívia: COMO a rotina interna da operação funciona (gatilho, passos, dono, controles). Felipe: O QUE existe e QUANDO vence (documentos, fornecedores, prazos, com fonte).","entre":"Olívia e Felipe"},{"como":"Olívia: procedimento para a SUA equipe. Isabela: treinamento para pessoa leiga DE FORA (participante ou cliente).","entre":"Olívia e Isabela"},{"como":"Augusto: onde jogar (opções de negócio). Camila: como atrair (campanha e experimento, sem texto final). Nina: o que construir no produto (problema e requisitos).","entre":"Augusto, Camila e Nina"},{"como":"Camila planeja a campanha para muitas pessoas; Isabela escreve o texto final; Victor monta a abordagem um a um.","entre":"Camila, Isabela e Victor"},{"como":"Joana: rascunho de resposta a UMA solicitação, com a categoria do caso. Renata: plano de sucesso e retenção. Daniel: lote de reclamações, contagem e tendência.","entre":"Renata, Joana e Daniel"},{"como":"Caio: dinheiro (valores, caixa, custo, margem, cenários). Felipe: agenda de vencimentos e documentos, sem valores de caixa. Daniel: indicadores que não são dinheiro (funil, uso, atendimento).","entre":"Caio, Felipe e Daniel"},{"como":"Laura: só o seu desenvolvimento pessoal (escopo PESSOAL). Bianca: funções, vagas e desempenho das empresas.","entre":"Laura e Bianca"},{"como":"A Helena revisa só cálculo, parecer e prática pessoal; as outras revisões estão distribuídas (servicos.yaml, MAT-08). O Caio é o revisor titular do convite e do roteiro de treinamento desde a v2.0, porque a regra 4 tira a Helena dessas peças (ela revisa o parecer que as julga).","entre":"Helena e as revisões"}],"versao":"3.1.0"},"helena-v2/playbooks/recrutar-10-pessoas.yaml":{"acoes_do_fundador":[{"acao_do_fundador":"AF-TREINAMENTO-ENVIAR","descricao":"Enviar o roteiro de treinamento aprovado às pessoas que aceitarem o convite.","etapa":"E2"},{"acao_do_fundador":"AF-COPY-ENVIAR-OU-PUBLICAR","descricao":"Enviar o convite aprovado às 10 primeiras pessoas, por WhatsApp e redes.","etapa":"E3"}],"decisoes":["DEC-024","DEC-025"],"empresas":["BIZ-003"],"entradas_externas":{"condicoes_participante":"JOB-HR-f6d55eff0523a50f07397cffbfbe313d","pesquisa_indicacao_equipe":"JOB-HR-0ed988ddf445b819ca5833dfa79831e9","pesquisa_mimix_hub":"JOB-HR-a5dabb24ffdbdaa016299f0e5e3def89"},"etapas":[{"depende_de":[],"entradas":["pesquisa_indicacao_equipe","condicoes_participante"],"id":"E1","objetivo":"Conta da receita com 10 pessoas, em três cenários, e quanto cada participante recebe, usando apenas horas, taxa aplicável, beneficiário e pagador confirmados com origem. A referência de US$ 0,50 não é tarifa contratada: se faltar comprovação, registrar os dados faltantes; cenários com premissas só depois de confirmação do Fundador.","servico":"SRV-CALCULO"},{"depende_de":[],"entradas":["pesquisa_mimix_hub","condicoes_participante"],"id":"E2","objetivo":"Como gravar atividades do dia a dia com qualidade e privacidade, para a pessoa não ser reprovada.","servico":"SRV-ROTEIRO-TREINAMENTO"},{"depende_de":[],"entradas":["condicoes_participante"],"id":"E3","objetivo":"Convite para as primeiras 10 pessoas (WhatsApp e redes), sem nenhuma promessa de renda.","servico":"SRV-COPY"},{"depende_de":["E2","E3"],"entradas":["E2","E3","condicoes_participante"],"id":"E4","julga":["E2","E3"],"objetivo":"O convite (E3) e o roteiro (E2) podem ser usados? Riscos de imagem, voz, terceiros e LGPD, com o ajuste concreto por peça e a conclusão sobre o cadastro na Mimix e no Hub (PF-01).","se_semaforo":{"AJUSTE":{"max_ciclos":2,"refazer":["E2","E3"]},"NAO_PODE":{"aguardar_fundador":true}},"servico":"SRV-PARECER"},{"depende_de":["E1","E2","E3","E4"],"entradas":["E1","E2","E3","E4"],"id":"E5","objetivo":"Plano dos 7 dias para o Fundador, em linguagem simples: o que cada etapa aprovou, o que só ele faz (cadastro na Mimix e no Hub, envio do roteiro e do convite) e como acompanhar as primeiras horas aprovadas.","servico":"SRV-RELATORIO-FINAL"}],"id":"recrutar-10-pessoas","nome":"Recrutar as primeiras 10 pessoas na Mimix e no Hub","orcamento_meta":{"buscas":0,"chamadas_total":200,"execucoes":30,"partes_de_pagina":90},"passos_fixos_do_fundador":[{"categorias":["CADASTRO"],"coberto_pelo_parecer":"E4","id":"PF-01","texto":"Cadastrar a Humano Digital na Mimix e no Hub e configurar a indicação."}],"prazo_sugerido_dias":7,"versao":"3.1.0"},"helena-v2/schemas/acao.schema.json":{"$defs":{"DEVOLVER_A_QUEM_PEDIU":{"additionalProperties":false,"properties":{"acao":{"const":"DEVOLVER_A_QUEM_PEDIU"},"explicacao":{"maxLength":500,"minLength":10,"type":"string"},"motivo":{"enum":["PEDIDO_AMBIGUO","PEDIDO_IMPOSSIVEL","FORA_DO_SERVICO","CONFLITA_COM_O_QUE_NAO_PODE"]}},"required":["acao","motivo","explicacao"],"type":"object"},"ENTREGAR":{"additionalProperties":false,"properties":{"acao":{"const":"ENTREGAR"},"acao_externa":{"$ref":"#/$defs/acao_externa_proposta"},"autoavaliacao":{"maxLength":200,"minLength":1,"type":"string"},"entrega":{"additionalProperties":{"$ref":"#/$defs/valor_de_secao"},"description":"Uma chave por seção do tipo de entrega (deliverables/<tipo>.yaml).","minProperties":1,"propertyNames":{"pattern":"^[a-z][a-z0-9_]*$"},"type":"object"},"parecer":{"description":"Só a etapa julgadora usa AJUSTE ou NAO_PODE; nas outras é sempre OK (passagens.yaml E20). No jurídico é o semáforo sobre as peças julgadas e os passos fixos do roteiro.","enum":["OK","AJUSTE","NAO_PODE"]}},"required":["acao","parecer","acao_externa","entrega"],"type":"object"},"LER_DE_VOLTA":{"additionalProperties":false,"description":"''Entendi assim... Confirma?'' (só no pedido grande; no pequeno vale na hora, com desfazer). A Helena escolhe; o código monta o grafo (servicos.yaml, montagem_do_plano). Empresa, prioridade e prazo do card NÃO vêm daqui: vêm da caixa Novo pedido, como toque seu.","properties":{"acao":{"const":"LER_DE_VOLTA"},"entendi_assim":{"additionalProperties":false,"properties":{"como_e_o_pronto":{"items":{"$ref":"#/$defs/item_do_pronto_proposto"},"maxItems":5,"minItems":1,"type":"array"},"nao_pode":{"items":{"maxLength":200,"minLength":3,"type":"string"},"type":"array"},"o_que_quer":{"maxLength":400,"minLength":10,"type":"string"}},"required":["o_que_quer","como_e_o_pronto","nao_pode"],"type":"object"},"escolha":{"$ref":"#/$defs/escolha_da_helena"},"prazo_sugerido":{"description":"Só sugestão: vira item na sua lista. O prazo do card só muda pelo seu botão MUDAR_PRAZO (regra 7).","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?-03:00$","type":"string"}},"required":["acao","escolha","entendi_assim"],"type":"object"},"PEDIR_SUBCARD_desligado":{"description":"PEDIR_SUBCARD existe no vocabulário mas está DESLIGADO até a fase 4 (MEL-24). Não faz parte de saida_do_autor: se chegar, não fecha o esquema e conta como FORMATO_ERRADO (regras_gerais.resposta_de_agente_sem_linha).","properties":{"acao":{"const":"PEDIR_SUBCARD"}},"required":["acao"],"type":"object"},"PERGUNTAR":{"additionalProperties":false,"description":"Vai pela Helena, com opções, dentro do limite de perguntas do card. O tipo da espera (interna ou externa) NÃO é escolha do agente: o código decide pelo roteiro (prazo_de_terceiro). Bloqueada quando a execução usou a internet (C-7).","properties":{"acao":{"const":"PERGUNTAR"},"opcoes":{"$ref":"#/$defs/opcoes_A_B_C"},"pergunta":{"maxLength":300,"minLength":10,"type":"string"},"recomendacao":{"enum":["A","B","C"]}},"required":["acao","pergunta","opcoes"],"type":"object"},"RECOMENDAR":{"additionalProperties":false,"description":"Só quando a Helena NÃO é autora nem revisora designada da etapa em resolução (servicos.yaml, MAT-26): nesse caso o motor nem a chama.","properties":{"acao":{"const":"RECOMENDAR"},"motivo":{"maxLength":500,"minLength":10,"type":"string"},"opcao":{"enum":["REFAZER","SEGUIR_SEM","ENCERRAR"]}},"required":["acao","opcao","motivo"],"type":"object"},"REGISTRAR_FALHA":{"additionalProperties":false,"description":"Sempre conta como tentativa. O agente escreve só o motivo; o TIPO da falha é lido pelo motor no registro de uso e no veredito do validador, nunca no texto (C-20).","properties":{"acao":{"const":"REGISTRAR_FALHA"},"explicacao":{"maxLength":500,"minLength":10,"type":"string"},"motivo_falha":{"enum":["NAO_CONSIGO","FALTAM_DADOS","FONTE_INSUFICIENTE"]}},"required":["acao","motivo_falha","explicacao"],"type":"object"},"SUGERIR_PRAZO":{"additionalProperties":false,"description":"Só reação: vira item na sua lista. O prazo só muda pelo seu botão (regra 7).","properties":{"acao":{"const":"SUGERIR_PRAZO"},"motivo":{"maxLength":300,"minLength":10,"type":"string"},"prazo_sugerido":{"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?-03:00$","type":"string"}},"required":["acao","prazo_sugerido","motivo"],"type":"object"},"acao_externa_proposta":{"description":"Parâmetro acao_externa de ENTREGAR (maquina/vocabulario.yaml (versão 2.0.0)). O agente só diz NENHUMA ou SO_FUNDADOR com o id da ação, da lista fechada do catálogo; nunca escreve texto sobre a ação (o texto que você vê vem da descrição fixa da ação e do roteiro). PELO_MOTOR não é aceito (nenhum serviço o libera; MAT-11). Fica guardado na etapa e só vira proposta na sua lista quando o card fica PRONTO (E110), no máximo uma por etapa. A CHK-COMUM-10 confere que o id é o que o plano deu àquela etapa.","oneOf":[{"additionalProperties":false,"properties":{"tipo":{"const":"NENHUMA"}},"required":["tipo"],"type":"object"},{"additionalProperties":false,"properties":{"acao_do_fundador":{"description":"Uma das ações do fundador de servicos.yaml (lista fechada).","enum":["AF-ADMIN-PAGAR-RENOVAR-ASSINAR","AF-PESSOAS-PUBLICAR-VAGA","AF-TECNICA-CONTRATAR-SERVICO","AF-CAMPANHA-LANCAR","AF-COPY-ENVIAR-OU-PUBLICAR","AF-TREINAMENTO-ENVIAR","AF-VENDAS-CONTATAR","AF-PARCERIA-CONTATAR","AF-SUCESSO-FALAR-COM-CLIENTE","AF-ATENDIMENTO-ENVIAR-RESPOSTA"]},"tipo":{"const":"SO_FUNDADOR"}},"required":["tipo","acao_do_fundador"],"type":"object"}]},"botao_APROVAR":{"additionalProperties":false,"properties":{"acao":{"const":"APROVAR"}},"required":["acao"],"type":"object"},"botao_CANCELAR":{"additionalProperties":false,"properties":{"acao":{"const":"CANCELAR"},"confirmado":{"const":true},"encaminhar_para_v1":{"description":"Só com o card em ESPERANDO_CONFIRMACAO: o código cria o trabalho na v1 com o seu pedido original e grava o número no card (servicos.yaml, destino_fora_da_v2). A passagem é a mesma do Cancelar (C22, fim FUNDADOR).","type":"boolean"}},"required":["acao","confirmado"],"type":"object"},"botao_MUDAR_PRAZO":{"additionalProperties":false,"properties":{"acao":{"const":"MUDAR_PRAZO"},"prazo":{"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?-03:00$","type":"string"}},"required":["acao","prazo"],"type":"object"},"botao_MUDAR_PRIORIDADE":{"additionalProperties":false,"properties":{"acao":{"const":"MUDAR_PRIORIDADE"},"prioridade":{"maximum":5,"minimum":1,"type":"integer"}},"required":["acao","prioridade"],"type":"object"},"botao_PAUSAR_TUDO":{"additionalProperties":false,"properties":{"acao":{"const":"PAUSAR_TUDO"}},"required":["acao"],"type":"object"},"botao_PEDIR_AJUSTE":{"additionalProperties":false,"properties":{"acao":{"const":"PEDIR_AJUSTE"},"comentario":{"maxLength":1000,"minLength":1,"type":"string"},"motivo_ajuste":{"enum":["ERRO_DE_FATO","FALTOU_TEMA","TOM","FORMATO"]}},"required":["acao","motivo_ajuste"],"type":"object"},"botao_RESPONDER":{"additionalProperties":false,"allOf":[{"if":{"properties":{"opcao":{"not":{"const":"CONFIRMO"}}}},"then":{"not":{"required":["escolha"]}}}],"properties":{"acao":{"const":"RESPONDER"},"escolha":{"description":"Só no CONFIRMO de um card em ESPERANDO_CONFIRMACAO (motivo NENHUM ou HELENA_FALHOU; C06): o serviço ou roteiro que você escolheu na lista do app. Substitui a escolha da Helena. Sem escolha válida, o validador do plano recusa (PLANO_INVALIDO).","oneOf":[{"additionalProperties":false,"properties":{"id":{"enum":["SRV-CALCULO","SRV-COPY","SRV-ROTEIRO-TREINAMENTO"]},"tipo":{"const":"SERVICO"}},"required":["tipo","id"],"type":"object"},{"additionalProperties":false,"properties":{"id":{"maxLength":80,"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$","type":"string"},"tipo":{"const":"ROTEIRO"}},"required":["tipo","id"],"type":"object"}]},"opcao":{"enum":["RESPOSTA_A","RESPOSTA_B","RESPOSTA_C","CONFIRMO","REFAZER","SEGUIR_SEM","ENCERRAR","PULAR","ESPERAR","MODELO_MENOR","ACONTECEU","NAO_ACONTECEU","FEITO_POR_MIM"]},"pergunta_id":{"maxLength":80,"minLength":1,"type":"string"}},"required":["acao","pergunta_id","opcao"],"type":"object"},"botao_USAR_COMO_EXEMPLO":{"additionalProperties":false,"properties":{"acao":{"const":"USAR_COMO_EXEMPLO"}},"required":["acao"],"type":"object"},"citacao":{"additionalProperties":false,"description":"Citação: trecho contínuo (12 palavras ou mais, ou frase inteira) conferido pelo código contra a cópia guardada. Nunca confia num endereço escrito pelo agente (MEL-27 b). Exatamente uma origem.","oneOf":[{"not":{"required":["fonte_importada_id"]},"required":["leitura_id","parte"]},{"not":{"anyOf":[{"required":["leitura_id"]},{"required":["parte"]}]},"required":["fonte_importada_id"]}],"properties":{"fonte_importada_id":{"description":"Fonte importada que veio no pacote (pesquisa aprovada, tabela de leis).","pattern":"^FON-[A-Za-z0-9-]+$","type":"string"},"leitura_id":{"description":"Cópia de página lida NESTA execução pela nossa ferramenta.","pattern":"^LEI-[A-Za-z0-9-]+$","type":"string"},"parte":{"minimum":1,"type":"integer"},"traducao":{"maxLength":2000,"minLength":1,"type":"string"},"trecho_original":{"maxLength":2000,"minLength":1,"type":"string"}},"required":["trecho_original"],"type":"object"},"escolha_da_helena":{"description":"A Helena só escolhe: 1 serviço que recebe card (e que o código sabe montar sozinho), 1 roteiro, ou FORA_DA_V2. Os ids de serviço vêm de servicos.yaml (escolhivel, avulso e em ESTAGIO/ATIVO nesta versão do catálogo); o validador do plano confere o estado na hora. Não existe ''nenhum'' com pergunta A/B/C: não há passagem para essa resposta no card.","oneOf":[{"additionalProperties":false,"properties":{"id":{"enum":["SRV-CALCULO","SRV-COPY","SRV-ROTEIRO-TREINAMENTO"]},"tipo":{"const":"SERVICO"}},"required":["tipo","id"],"type":"object"},{"additionalProperties":false,"properties":{"id":{"maxLength":80,"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$","type":"string"},"tipo":{"const":"ROTEIRO"}},"required":["tipo","id"],"type":"object"},{"additionalProperties":false,"description":"O pedido ainda não roda na v2 (servicos.yaml, destino_fora_da_v2). O card vira pedido grande e mostra a você quem atenderia; você encaminha à v1, escolhe outro serviço ou cancela.","not":{"required":["servico_que_atenderia","roteiro_que_atenderia"]},"properties":{"roteiro_que_atenderia":{"maxLength":80,"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$","type":"string"},"servico_que_atenderia":{"enum":["SRV-PLANO-DE-PRATICA","SRV-ANALISE-ESTRATEGICA","SRV-PLANO-DE-PROJETO","SRV-CALCULO","SRV-ANALISE-DE-DADOS","SRV-CONTROLE-ADMINISTRATIVO","SRV-PERFIL-DE-FUNCAO","SRV-REQUISITOS-DE-PRODUTO","SRV-ESPECIFICACAO-DE-INTERFACE","SRV-PROPOSTA-TECNICA","SRV-PLANO-DE-TESTES","SRV-DOSSIE","SRV-PLANO-DE-CAMPANHA","SRV-COPY","SRV-ROTEIRO-TREINAMENTO","SRV-ROTEIRO-COMERCIAL","SRV-TESE-DE-PARCERIA","SRV-PLANO-DE-SUCESSO","SRV-RASCUNHO-DE-RESPOSTA","SRV-PROCEDIMENTO-OPERACIONAL"]},"tipo":{"const":"FORA_DA_V2"}},"required":["tipo"],"type":"object"}]},"item_com_citacao":{"additionalProperties":false,"properties":{"citacoes":{"items":{"$ref":"#/$defs/citacao"},"minItems":1,"type":"array"},"texto":{"maxLength":1500,"minLength":1,"type":"string"}},"required":["texto","citacoes"],"type":"object"},"item_do_pronto_proposto":{"additionalProperties":false,"allOf":[{"if":{"properties":{"quem_confere":{"const":"CODIGO"}}},"then":{"required":["checagem"]}}],"properties":{"checagem":{"pattern":"^CHK-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"},"quem_confere":{"enum":["CODIGO","IA","FUNDADOR"]},"risco":{"enum":["ALTO","BAIXO"]},"texto":{"maxLength":200,"minLength":3,"type":"string"}},"required":["texto","quem_confere","risco"],"type":"object"},"numero":{"additionalProperties":false,"allOf":[{"if":{"properties":{"origem":{"const":"FONTE_CITADA"}}},"then":{"required":["citacao","data_da_fonte"]}},{"if":{"properties":{"origem":{"enum":["ENTREGA_APROVADA","CALCULADO","DADO_DO_FUNDADOR"]}}},"then":{"required":["ref"]}}],"description":"Número com unidade e origem (C-9, M-16, K-8). Câmbio só com fonte datada ou dado seu.","properties":{"citacao":{"$ref":"#/$defs/citacao"},"data_da_fonte":{"format":"date","type":"string"},"origem":{"enum":["DADO_DO_FUNDADOR","FONTE_CITADA","ENTREGA_APROVADA","PREMISSA","CALCULADO"]},"ref":{"maxLength":120,"minLength":1,"type":"string"},"unidade":{"maxLength":30,"minLength":1,"type":"string"},"valor":{"type":"number"}},"required":["valor","unidade","origem"],"type":"object"},"opcao_de_pergunta":{"additionalProperties":false,"properties":{"consequencia":{"maxLength":200,"minLength":2,"type":"string"},"letra":{"enum":["A","B","C"]},"texto":{"maxLength":160,"minLength":2,"type":"string"}},"required":["letra","texto","consequencia"],"type":"object"},"opcoes_A_B_C":{"description":"A, B e (opcional) C, nessa ordem. Sua resposta chega como RESPONDER RESPOSTA_A/B/C na etapa que perguntou (ESPERANDO_FUNDADOR com motivo PERGUNTA).","items":false,"maxItems":3,"minItems":2,"prefixItems":[{"allOf":[{"$ref":"#/$defs/opcao_de_pergunta"},{"properties":{"letra":{"const":"A"}}}]},{"allOf":[{"$ref":"#/$defs/opcao_de_pergunta"},{"properties":{"letra":{"const":"B"}}}]},{"allOf":[{"$ref":"#/$defs/opcao_de_pergunta"},{"properties":{"letra":{"const":"C"}}}]}],"type":"array"},"saida_da_helena":{"oneOf":[{"$ref":"#/$defs/LER_DE_VOLTA"},{"$ref":"#/$defs/RECOMENDAR"},{"$ref":"#/$defs/SUGERIR_PRAZO"}]},"saida_do_autor":{"description":"Exatamente UMA ação do AUTOR. Resposta sem ação, com duas ações ou fora do formato é FORMATO_ERRADO (uma nova tentativa só de formato; K-13).","oneOf":[{"$ref":"#/$defs/ENTREGAR"},{"$ref":"#/$defs/PERGUNTAR"},{"$ref":"#/$defs/DEVOLVER_A_QUEM_PEDIU"},{"$ref":"#/$defs/REGISTRAR_FALHA"}]},"saida_do_revisor":{"additionalProperties":false,"description":"Um veredito por critério da rubrica e por item CARD-n marcado IA. Faltar um ID ou trazer ID desconhecido é FORMATO_ERRADO. O revisor nunca escolhe APROVAR ou REPROVAR: o código calcula (x-evento-calculado). O texto do cartão para você é montado pelo código, nunca com as palavras do revisor.","properties":{"vereditos":{"items":{"$ref":"#/$defs/veredito"},"minItems":1,"type":"array"}},"required":["vereditos"],"type":"object","x-evento-calculado":["algum FALHOU, ou NAO_CONSIGO_CONFERIR com FALTA_PROVA_NA_ENTREGA -> REPROVAR (volta ao autor; conta reprovação)","senão, algum NAO_CONSIGO_CONFERIR com FORA_DO_ALCANCE em critério de risco ALTO -> NAO_CONSIGO_CONFERIR (cartão de revisão para você)","senão -> APROVAR (NAO_CONSIGO_CONFERIR de risco BAIXO fica ''sem conferir'' na faixa e a entrega não pode virar ''Usar como exemplo'')","PASSOU em critério TRECHO exige ''trecho'', que o código confere literalmente na entrega ou na cópia lida"]},"toque_do_fundador":{"description":"Um botão do app (vocabulario.botoes_do_fundador). Texto fora de botão vira comentário e nunca muda estado (MEL-25).","oneOf":[{"$ref":"#/$defs/botao_APROVAR"},{"$ref":"#/$defs/botao_PEDIR_AJUSTE"},{"$ref":"#/$defs/botao_USAR_COMO_EXEMPLO"},{"$ref":"#/$defs/botao_CANCELAR"},{"$ref":"#/$defs/botao_RESPONDER"},{"$ref":"#/$defs/botao_PAUSAR_TUDO"},{"$ref":"#/$defs/botao_MUDAR_PRIORIDADE"},{"$ref":"#/$defs/botao_MUDAR_PRAZO"}]},"valor_de_secao":{"description":"A forma exigida em cada seção vem do tipo de entrega (deliverables/<tipo>.yaml, secoes[].tipo_de_campo); o código confere.","oneOf":[{"$ref":"#/$defs/valor_texto"},{"$ref":"#/$defs/valor_lista"},{"$ref":"#/$defs/valor_tabela"},{"$ref":"#/$defs/numero"},{"$ref":"#/$defs/citacao"}]},"valor_lista":{"items":{"oneOf":[{"maxLength":1500,"minLength":1,"type":"string"},{"$ref":"#/$defs/item_com_citacao"}]},"type":"array"},"valor_tabela":{"items":{"additionalProperties":{"oneOf":[{"maxLength":1500,"type":"string"},{"type":"number"},{"$ref":"#/$defs/numero"},{"$ref":"#/$defs/citacao"}]},"minProperties":1,"type":"object"},"type":"array"},"valor_texto":{"maxLength":12000,"minLength":1,"type":"string"},"veredito":{"additionalProperties":false,"allOf":[{"if":{"properties":{"veredito":{"const":"FALHOU"}}},"then":{"anyOf":[{"required":["trecho"]},{"required":["secao"]}]}},{"else":{"not":{"required":["motivo_nao_confere"]}},"if":{"properties":{"veredito":{"const":"NAO_CONSIGO_CONFERIR"}}},"then":{"required":["motivo_nao_confere"]}}],"properties":{"criterio":{"pattern":"^(RUB-[A-Z0-9]+(-[A-Z0-9]+)*-[0-9]{2}|CARD-[1-5])$","type":"string"},"justificativa":{"maxLength":280,"minLength":1,"type":"string"},"motivo_nao_confere":{"enum":["FALTA_PROVA_NA_ENTREGA","FORA_DO_ALCANCE"]},"secao":{"pattern":"^[a-z][a-z0-9_]*$","type":"string"},"trecho":{"maxLength":1500,"minLength":1,"type":"string"},"veredito":{"enum":["PASSOU","FALHOU","NAO_CONSIGO_CONFERIR"]}},"required":["criterio","veredito"],"type":"object"}},"$id":"helena-v2/acao","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"allOf":[{"if":{"properties":{"evento":{"const":"ENTREGAR"},"papel":{"const":"AUTOR"}},"required":["papel","evento"]},"then":{"properties":{"saida":{"properties":{"acao":{"const":"ENTREGAR"}}}}}},{"if":{"properties":{"evento":{"const":"PERGUNTAR"},"papel":{"const":"AUTOR"}},"required":["papel","evento"]},"then":{"properties":{"saida":{"properties":{"acao":{"const":"PERGUNTAR"}}}}}},{"if":{"properties":{"evento":{"const":"DEVOLVER_A_QUEM_PEDIU"},"papel":{"const":"AUTOR"}},"required":["papel","evento"]},"then":{"properties":{"saida":{"properties":{"acao":{"const":"DEVOLVER_A_QUEM_PEDIU"}}}}}},{"if":{"properties":{"evento":{"const":"REGISTRAR_FALHA"},"papel":{"const":"AUTOR"}},"required":["papel","evento"]},"then":{"properties":{"saida":{"properties":{"acao":{"const":"REGISTRAR_FALHA"}}}}}},{"if":{"properties":{"evento":{"const":"LER_DE_VOLTA"},"papel":{"const":"HELENA"}},"required":["papel","evento"]},"then":{"properties":{"saida":{"properties":{"acao":{"const":"LER_DE_