}]}}}}}},{"if":{"properties":{"papel":{"const":"AUTOR"}},"required":["papel"]},"then":{"not":{"anyOf":[{"required":["id_toque"]},{"required":["versao_vista"]}]},"properties":{"ator":{"enum":["HELENA","LAURA","AUGUSTO","MARINA","CAIO","CLARA","BIANCA","DANIEL","THEO","NINA","RAVI","MAYA","BRUNO","OLIVIA","VICTOR","CAMILA","ISABELA","PEDRO","RENATA","JOANA","FELIPE"]},"evento":{"enum":["ENTREGAR","PERGUNTAR","DEVOLVER_A_QUEM_PEDIU","REGISTRAR_FALHA"]},"saida":{"$ref":"#/$defs/saida_do_autor"}},"required":["etapa_id","ator","numero_de_execucao","usou_internet","saida"]}},{"if":{"properties":{"papel":{"const":"REVISOR"}},"required":["papel"]},"then":{"not":{"anyOf":[{"required":["usou_internet"]},{"required":["id_toque"]},{"required":["versao_vista"]}]},"properties":{"ator":{"enum":["HELENA","LAURA","AUGUSTO","MARINA","CAIO","CLARA","BIANCA","DANIEL","THEO","NINA","RAVI","MAYA","BRUNO","OLIVIA","VICTOR","CAMILA","ISABELA","PEDRO","RENATA","JOANA","FELIPE"]},"evento":{"enum":["APROVAR","REPROVAR","NAO_CONSIGO_CONFERIR"]},"saida":{"$ref":"#/$defs/saida_do_revisor"}},"required":["etapa_id","ator","numero_de_execucao","saida"]}},{"if":{"properties":{"papel":{"const":"HELENA"}},"required":["papel"]},"then":{"not":{"anyOf":[{"required":["usou_internet"]},{"required":["id_toque"]},{"required":["versao_vista"]}]},"properties":{"ator":{"const":"HELENA"},"evento":{"enum":["LER_DE_VOLTA","RECOMENDAR","SUGERIR_PRAZO"]},"saida":{"$ref":"#/$defs/saida_da_helena"}},"required":["numero_de_execucao","saida"]}},{"if":{"properties":{"papel":{"const":"FUNDADOR"}},"required":["papel"]},"then":{"not":{"anyOf":[{"required":["usou_internet"]},{"required":["numero_de_execucao"]}]},"properties":{"ator":{"const":"FUNDADOR"},"evento":{"enum":["APROVAR","PEDIR_AJUSTE","USAR_COMO_EXEMPLO","CANCELAR","RESPONDER","PAUSAR_TUDO","MUDAR_PRIORIDADE","MUDAR_PRAZO"]},"saida":{"$ref":"#/$defs/toque_do_fundador"}},"required":["id_toque","saida"]}},{"description":"passagens.yaml regras_gerais.toques_do_fundador_exigem_versao_vista: com versão antiga, viram comentário e nunca mudam estado.","if":{"properties":{"evento":{"enum":["APROVAR","PEDIR_AJUSTE","RESPONDER"]},"papel":{"const":"FUNDADOR"}},"required":["papel","evento"]},"then":{"required":["versao_vista"]}}],"description":"Registro de UMA resposta, gravado pelo MOTOR: a saída que o agente, a Helena ou você produziu, mais os campos que só o motor preenche (chave da execução, usou_internet, número do toque). Os nomes de ação são os de maquina/vocabulario.yaml (versão 2.0.0): 4 ações do AUTOR liberadas (PEDIR_SUBCARD desligado), 3 do REVISOR (calculadas pelo código a partir dos vereditos), 3 da HELENA e os 8 botões do FUNDADOR. O agente valida a própria saída contra $defs/saida_do_autor, $defs/saida_do_revisor ou $defs/saida_da_helena; o envelope confere também a lista fechada de ações do fundador de cada agente.","properties":{"acao_externa_id":{"pattern":"^A[0-9]{1,3}$","type":"string"},"ator":{"enum":["HELENA","LAURA","AUGUSTO","MARINA","CAIO","CLARA","BIANCA","DANIEL","THEO","NINA","RAVI","MAYA","BRUNO","OLIVIA","VICTOR","CAMILA","ISABELA","PEDRO","RENATA","JOANA","FELIPE","FUNDADOR"]},"card_id":{"maxLength":80,"minLength":1,"type":"string"},"etapa_id":{"pattern":"^E[0-9]{1,2}$","type":"string"},"evento":{"pattern":"^[A-Z][A-Z0-9_]+$","type":"string"},"id_toque":{"maxLength":80,"minLength":1,"type":"string"},"numero_de_execucao":{"description":"Chave da chamada (regra 3): sequência do banco, monotônica, nunca zera e nunca é ''execucoes'' (passagens.yaml regras_gerais.numero_de_execucao). Resposta com número antigo não grava.","minimum":1,"type":"integer"},"papel":{"enum":["AUTOR","REVISOR","HELENA","FUNDADOR"]},"recebido_em":{"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?-03:00$","type":"string"},"saida":{"type":"object"},"usou_internet":{"description":"Preenchido pelo MOTOR a partir do registro de uso da mesma execução (contagem do nosso servidor de ferramentas), nunca pelo agente.","enum":["NAO","SIM"]},"versao_vista":{"description":"Versão da peça (card, etapa ou ação) que você viu ao tocar.","minimum":1,"type":"integer"}},"required":["papel","evento","card_id","recebido_em"],"title":"Ação tipada de cada papel (v3.1)","type":"object","x-regras-do-validador":["CHK-COMUM-10 (portão 1): acao_externa.tipo está em acao_externa_permitida do serviço da etapa; com SO_FUNDADOR, acao_do_fundador está em acoes_do_fundador do serviço e é a ação que o plano deu àquela etapa (no avulso, a única do serviço); senão PORTAO1_RECUSOU com o item exato, e nada nasce na E110","PELO_MOTOR nunca é aceito na saída do agente enquanto nenhum serviço o liberar (MAT-11); o vocabulário mantém o nome para a fase 4","RECOMENDAR só grava se o motor chamou a Helena com a chave atual; o motor não a chama quando ela é autora ou revisora designada da etapa (MAT-26)","CANCELAR com encaminhar_para_v1 só vale com o card em ESPERANDO_CONFIRMACAO; em outro estado, é um Cancelar comum e o app avisa","RESPONDER CONFIRMO com escolha só vale em ESPERANDO_CONFIRMACAO com motivo NENHUM ou HELENA_FALHOU; em outro motivo, a escolha é ignorada e o app avisa"]},"helena-v2/schemas/agent.schema.json":{"$defs":{"aprendizado":{"additionalProperties":false,"allOf":[{"if":{"properties":{"estado":{"const":"ATIVA"}}},"then":{"required":["prova","ativada_em"]}}],"description":"Lição com versão. Nasce PROPOSTA e fica inativa até passar pela bateria de testes do serviço; aprovar uma entrega nunca vira lição (C-18, FC-13). Só ATIVA entra no pacote do agente.","properties":{"ativada_em":{"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?-03:00$","type":"string"},"estado":{"enum":["PROPOSTA","EM_PROVA","ATIVA","REVOGADA"]},"id":{"pattern":"^LIC-[0-9]{4}$","type":"string"},"origem":{"additionalProperties":false,"properties":{"card_id":{"maxLength":80,"minLength":1,"type":"string"},"motivo_ajuste":{"enum":["ERRO_DE_FATO","FALTOU_TEMA","TOM","FORMATO"]},"tipo":{"enum":["PEDIR_AJUSTE","NUNCA_FACA_ISSO","VALE_SEMPRE","CORRECAO_REPETIDA_3_VEZES"]}},"required":["tipo","card_id"],"type":"object"},"prova":{"additionalProperties":false,"properties":{"casos":{"items":{"maxLength":120,"minLength":1,"type":"string"},"minItems":1,"type":"array"},"resultado":{"const":"3 de 3 em todos os casos"},"versao_da_ficha":{"maxLength":20,"minLength":1,"type":"string"}},"required":["casos","resultado","versao_da_ficha"],"type":"object"},"regra":{"maxLength":240,"minLength":10,"type":"string"},"servico":{"pattern":"^SRV-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"}},"required":["id","servico","regra","origem","estado"],"type":"object"},"aptidao":{"additionalProperties":false,"description":"Aptidão de revisão do par (este agente, tipo). Igual a servicos.yaml agentes.<identidade>.revisa (fonte única). APTA só depois do teste 9 do par com a rubrica atual e do seu toque, registrados na publicação; só você muda; o disjuntor nunca mexe (servicos.yaml, aptidao_de_revisao).","properties":{"estado":{"enum":["SEM_PROVA","APTA","PAUSADA"]},"tipo":{"pattern":"^[a-z][a-z0-9_]*$","type":"string"}},"required":["tipo","estado"],"type":"object"},"coordenacao":{"additionalProperties":false,"description":"Só a Helena: as respostas do papel HELENA (não são serviços). Sem ferramenta e com modelo.coordenacao. O estado é independente do serviço de relatório e das aptidões de revisão: só você muda (servicos.yaml, estado_da_coordenacao). SUGERIR_PRAZO é só reação e não roda execução própria.","properties":{"LER_DE_VOLTA":{"$ref":"#/$defs/so_resposta"},"RECOMENDAR":{"$ref":"#/$defs/so_resposta"},"estado":{"enum":["ATIVA","PAUSADA"]}},"required":["estado","LER_DE_VOLTA","RECOMENDAR"],"type":"object"},"ferramenta":{"additionalProperties":false,"allOf":[{"if":{"properties":{"nome":{"const":"ler_pagina"}}},"then":{"properties":{"desde":{"const":"fase 3"}}}},{"if":{"properties":{"nome":{"const":"buscar"}}},"then":{"properties":{"desde":{"const":"fase 4"}}}}],"description":"Uma das NOSSAS ferramentas (servicos.yaml, ferramentas_nossas). Só leem: efeito LER, com o acesso_sem_efeito do catálogo (só GET, sem cookie, sem login, sem caminho de ação, sem consulta com token, sem redirecionamento para outro domínio, só fonte que você ligou como ''pode ler''). Nenhuma ferramenta grava ou age fora (B-6, B-17, K-19).","properties":{"desde":{"description":"A ferramenta só entra no perfil a partir desta fase (MEL-34).","enum":["fase 3","fase 4"]},"efeito":{"const":"LER"},"nome":{"enum":["ler_pagina","buscar"]}},"required":["nome","efeito","desde"],"type":"object"},"modelo":{"additionalProperties":false,"description":"Apelido de models.yaml por papel, nunca o nome do modelo. Cada apelido só no papel dele (models.yaml, papel_do_apelido).","properties":{"autor":{"description":"Para os serviços de que o agente é dono. Serviço com leitura de página usa pesquisa-padrao.","enum":["analise-padrao","pesquisa-padrao","conteudo-padrao"]},"coordenacao":{"const":"coordenacao-padrao","description":"Só a Helena (leitura de volta e recomendação)."},"revisao":{"const":"revisao-padrao","description":"Toda revisão usa o mesmo apelido (MAT-10)."}},"required":["autor","revisao"],"type":"object"},"orcamento":{"additionalProperties":false,"description":"Orçamento de UMA execução do serviço, em chamadas ao nosso servidor de ferramentas e em tempo (no modo do Hermes que usamos não existe limite de passos; FC-1, M-3, C-3). No limite, o servidor responde ''entregue agora''; se o agente insistir 3 vezes, a execução termina como LIMITE_CHAMADAS. O tempo é cortado pelo motor.","properties":{"buscas":{"maximum":10,"minimum":0,"type":"integer"},"chamadas_total":{"description":"Todas as chamadas da execução, incluindo a resposta final.","maximum":60,"minimum":1,"type":"integer"},"partes_de_pagina":{"description":"Partes de até 20 mil caracteres entregues por ler_pagina.","maximum":40,"minimum":0,"type":"integer"},"tempo_s":{"description":"Tempo máximo da execução (prazo do estado EXECUTANDO, passagens.yaml tempo_maximo_da_ficha). Exemplo do plano: Clara 900 s.","maximum":900,"minimum":60,"type":"integer"}},"required":["buscas","partes_de_pagina","chamadas_total","tempo_s"],"type":"object","x-regras-do-validador":["chamadas_total >= buscas + partes_de_pagina + 1 (orçamento possível; M-3)","a soma das buscas das etapas de um roteiro cabe no orcamento_meta.buscas dele (furo 9)"]},"revisao":{"additionalProperties":false,"description":"Como este agente revisa (papel REVISOR). Revisão roda sempre sem ferramenta e com modelo.revisao: o código entrega o parágrafo em volta de cada citação (MAT-10). O tempo é o prazo do estado REVISAO (prazo_da_revisao). Só é designado para tipo com aptidão APTA (MAT-21).","properties":{"aptidao":{"description":"Um item por tipo em que o agente é revisor titular ou reserva no catálogo; vazia se não revisa nada.","items":{"$ref":"#/$defs/aptidao"},"type":"array"},"ferramentas":{"maxItems":0,"type":"array"},"orcamento":{"additionalProperties":false,"properties":{"chamadas_total":{"maximum":3,"minimum":1,"type":"integer"},"tempo_s":{"maximum":600,"minimum":60,"type":"integer"}},"required":["chamadas_total","tempo_s"],"type":"object"}},"required":["aptidao","ferramentas","orcamento"],"type":"object"},"servico_da_ficha":{"additionalProperties":false,"allOf":[{"description":"Quem lê a internet só entrega ou registra falha (C-7).","if":{"properties":{"ferramentas":{"minItems":1}},"required":["ferramentas"]},"then":{"properties":{"acoes_permitidas":{"items":{"enum":["ENTREGAR","REGISTRAR_FALHA"]}}}}},{"if":{"properties":{"ferramentas":{"not":{"contains":{"properties":{"nome":{"const":"buscar"}}}}}},"required":["ferramentas"]},"then":{"properties":{"orcamento":{"properties":{"buscas":{"const":0}}}}}},{"if":{"properties":{"ferramentas":{"not":{"contains":{"properties":{"nome":{"const":"ler_pagina"}}}}}},"required":["ferramentas"]},"then":{"properties":{"orcamento":{"properties":{"partes_de_pagina":{"const":0}}}}}}],"description":"Um serviço do catálogo de que este agente é dono (papel AUTOR). servico, tipo_de_entrega, acoes_permitidas, ferramentas, revisor e reserva têm de ser IGUAIS aos de servicos.yaml (fonte única); o validador recusa divergência. O orçamento é só da ficha. O estado do serviço (e o disjuntor) vale só para este papel de autor (MAT-13).","properties":{"acoes_permitidas":{"allOf":[{"contains":{"const":"ENTREGAR"}},{"contains":{"const":"REGISTRAR_FALHA"}}],"description":"Ações do papel AUTOR liberadas para o serviço (maquina/vocabulario.yaml (versão 2.0.0)). PEDIR_SUBCARD fica fora: desligado até a fase 4 (MEL-24). Sempre ENTREGAR e REGISTRAR_FALHA.","items":{"enum":["ENTREGAR","PERGUNTAR","DEVOLVER_A_QUEM_PEDIU","REGISTRAR_FALHA"]},"minItems":2,"type":"array","uniqueItems":true},"ferramentas":{"description":"Lista SEMPRE por extenso. Vazia é permitida e quer dizer: o perfil recebe o nosso servidor vazio (no Hermes, lista vazia liberaria todas; B-6). Antes de contar a execução, o motor confere que o agente recebeu exatamente estas (filtradas pela fase em curso).","items":{"$ref":"#/$defs/ferramenta"},"maxItems":2,"type":"array","uniqueItems":true},"orcamento":{"$ref":"#/$defs/orcamento"},"reserva":{"description":"Agente diferente do dono e do revisor, ou FUNDADOR. Você é sempre a última reserva, mesmo sem estar escrito. Só entra na lista efetiva com aptidão APTA (MAT-21).","enum":["HELENA","LAURA","AUGUSTO","MARINA","CAIO","CLARA","BIANCA","DANIEL","THEO","NINA","RAVI","MAYA","BRUNO","OLIVIA","VICTOR","CAMILA","ISABELA","PEDRO","RENATA","JOANA","FELIPE","FUNDADOR"]},"revisor":{"description":"Uma das 21 identidades de vocabulario.identidades.agentes (sem acento, como o banco grava).","enum":["HELENA","LAURA","AUGUSTO","MARINA","CAIO","CLARA","BIANCA","DANIEL","THEO","NINA","RAVI","MAYA","BRUNO","OLIVIA","VICTOR","CAMILA","ISABELA","PEDRO","RENATA","JOANA","FELIPE"]},"servico":{"pattern":"^SRV-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"},"tipo_de_entrega":{"description":"Arquivo deliverables/<tipo>.yaml.","pattern":"^[a-z][a-z0-9_]*$","type":"string"}},"required":["servico","tipo_de_entrega","acoes_permitidas","ferramentas","orcamento","revisor","reserva"],"type":"object"},"so_resposta":{"additionalProperties":false,"properties":{"ferramentas":{"description":"Sempre vazia: servidor vazio.","maxItems":0,"type":"array"},"orcamento":{"additionalProperties":false,"properties":{"chamadas_total":{"maximum":3,"minimum":1,"type":"integer"},"tempo_s":{"maximum":600,"minimum":60,"type":"integer"}},"required":["chamadas_total","tempo_s"],"type":"object"}},"required":["ferramentas","orcamento"],"type":"object"},"vagas":{"additionalProperties":false,"description":"Vagas do agente no motor (plano v3: 1 ou 2 por agente; a Helena tem uma vaga separada de coordenação). Falta de vaga nunca troca autor nem revisor: a etapa espera a vaga do designado (servicos.yaml, capacidade).","properties":{"coordenacao":{"const":1,"description":"Só a Helena: leitura de volta e recomendação, nunca atrás de uma revisão."},"trabalho":{"description":"Execuções de autor e de revisor deste agente ao mesmo tempo.","maximum":2,"minimum":1,"type":"integer"}},"required":["trabalho"],"type":"object"}},"$id":"helena-v2/agent","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"allOf":[{"else":{"not":{"required":["coordenacao"]},"properties":{"modelo":{"not":{"required":["coordenacao"]}},"papel":{"const":"ESPECIALISTA"},"vagas":{"not":{"required":["coordenacao"]}}}},"if":{"properties":{"identidade":{"const":"HELENA"}},"required":["identidade"]},"then":{"properties":{"modelo":{"required":["coordenacao"]},"papel":{"const":"COORDENADORA"},"vagas":{"required":["coordenacao"]}},"required":["coordenacao"]}},{"else":{"properties":{"empresas":{"items":{"enum":["BIZ-001","BIZ-002","BIZ-003","BIZ-004"]}}}},"if":{"properties":{"escopo":{"const":"PESSOAL"}},"required":["escopo"]},"then":{"properties":{"empresas":{"const":["PESSOAL"]}}}}],"description":"Ficha de um dos 21 agentes (agents/<nome-sem-acento-minusculo>.yaml). O perfil de cada execução é gerado desta ficha e do serviço pedido. Fonte única de: orçamento por serviço, orçamento de revisão, vagas, modelo por papel, regras, nunca e aprendizados. O resto é espelho conferido de organograma.yaml e servicos.yaml. Três estados separados (MAT-13): o do serviço (papel AUTOR), a aptidão de revisão por tipo e, só na Helena, o da coordenação; ''estado'' no topo é só o resumo para a tela. Nomes de maquina/vocabulario.yaml (versão 2.0.0).","properties":{"aprendizados":{"items":{"$ref":"#/$defs/aprendizado"},"type":"array"},"coordenacao":{"$ref":"#/$defs/coordenacao"},"empresas":{"description":"Empresas atendidas (a união das empresas dos serviços do agente no catálogo): BIZ-001 iGreen Energy, BIZ-002 Ecossistema de Saúde, BIZ-003 Humano Digital, BIZ-004 eLiving™; PESSOAL só a Laura.","items":{"enum":["BIZ-001","BIZ-002","BIZ-003","BIZ-004","PESSOAL"]},"minItems":1,"type":"array","uniqueItems":true},"escopo":{"enum":["EMPRESAS","PESSOAL"]},"estado":{"description":"Resumo para a tela, derivado dos serviços (servicos.yaml, MAT-13): ATIVO se algum serviço ATIVO; ESTAGIO se algum ESTAGIO; senão PAUSADO. Nunca usado para designar revisor nem para a coordenação.","enum":["ATIVO","ESTAGIO","PAUSADO"]},"fase_de_ativacao":{"enum":["v2.0","fase 3","fase 4"]},"funcao":{"maxLength":80,"minLength":3,"type":"string"},"grupo":{"pattern":"^GRP-[A-Z-]+$","type":"string"},"id":{"pattern":"^AGT-(0[1-9]|1[0-9]|2[01])$","type":"string"},"identidade":{"description":"Uma das 21 identidades de vocabulario.identidades.agentes (sem acento, como o banco grava).","enum":["HELENA","LAURA","AUGUSTO","MARINA","CAIO","CLARA","BIANCA","DANIEL","THEO","NINA","RAVI","MAYA","BRUNO","OLIVIA","VICTOR","CAMILA","ISABELA","PEDRO","RENATA","JOANA","FELIPE"]},"missao":{"maxLength":600,"minLength":10,"type":"string"},"modelo":{"$ref":"#/$defs/modelo"},"nome":{"maxLength":40,"minLength":2,"type":"string"},"nunca":{"items":{"maxLength":200,"minLength":5,"type":"string"},"maxItems":12,"minItems":1,"type":"array"},"papel":{"description":"Posição no organograma. Não é papel da máquina (AUTOR, REVISOR, HELENA).","enum":["COORDENADORA","ESPECIALISTA"]},"regras":{"items":{"maxLength":240,"minLength":5,"type":"string"},"maxItems":12,"minItems":1,"type":"array"},"revisao":{"$ref":"#/$defs/revisao"},"servicos":{"items":{"$ref":"#/$defs/servico_da_ficha"},"minItems":1,"type":"array"},"vagas":{"$ref":"#/$defs/vagas"},"versao":{"pattern":"^3\\.1\\.[0-9]+$","type":"string"}},"required":["versao","id","identidade","nome","funcao","papel","grupo","escopo","empresas","missao","servicos","revisao","modelo","vagas","regras","nunca","aprendizados","fase_de_ativacao","estado"],"title":"Ficha de agente (v3.1)","type":"object","x-regras-do-validador":["id, identidade, nome, funcao (=cargo), grupo, escopo, fase_de_ativacao e estado iguais à linha de organograma.yaml","arquivo = agents/<identidade em minúsculas>.yaml","servicos = exatamente os serviços de servicos.yaml com dono = identidade, com os mesmos campos; empresas = união das empresas desses serviços","revisao.aptidao = exatamente servicos.yaml agentes.<identidade>.revisa (mesmos tipos e mesmos estados)","revisor != identidade; reserva != identidade e != revisor (MAT-03)","modelo.autor = pesquisa-padrao se algum serviço do agente tem ferramenta; senão, outro apelido de AUTOR; modelo.revisao = revisao-padrao; modelo.coordenacao só na Helena (models.yaml, papel_do_apelido)","orcamento possível: chamadas_total >= buscas + partes_de_pagina + 1"]},"helena-v2/schemas/card.schema.json":{"$defs":{"etapa_do_plano":{"additionalProperties":false,"properties":{"acao_do_fundador":{"description":"A única ação do fundador que a entrega desta etapa pode propor (CHK-COMUM-10).","enum":["AF-ADMIN-PAGAR-RENOVAR-ASSINAR","AF-PESSOAS-PUBLICAR-VAGA","AF-TECNICA-CONTRATAR-SERVICO","AF-CAMPANHA-LANCAR","AF-COPY-ENVIAR-OU-PUBLICAR","AF-TREINAMENTO-ENVIAR","AF-VENDAS-CONTATAR","AF-PARCERIA-CONTATAR","AF-SUCESSO-FALAR-COM-CLIENTE","AF-ATENDIMENTO-ENVIAR-RESPOSTA"]},"autor":{"description":"Uma das 21 identidades de vocabulario.identidades.agentes (sem acento, como o banco grava).","enum":["HELENA","LAURA","AUGUSTO","MARINA","CAIO","CLARA","BIANCA","DANIEL","THEO","NINA","RAVI","MAYA","BRUNO","OLIVIA","VICTOR","CAMILA","ISABELA","PEDRO","RENATA","JOANA","FELIPE"]},"depende_de":{"items":{"pattern":"^E[0-9]{1,2}$","type":"string"},"type":"array","uniqueItems":true},"id":{"pattern":"^E[0-9]{1,2}$","type":"string"},"julga":{"items":{"pattern":"^E[0-9]{1,2}$","type":"string"},"minItems":1,"type":"array","uniqueItems":true},"revisores":{"contains":{"const":"FUNDADOR"},"description":"Revisores EFETIVOS (servicos.yaml, revisores_efetivos): [revisor, reserva] do serviço só com aptidão APTA no tipo, e FUNDADOR no fim. Pelo menos um agente. Congelada para a vida do card; é a lista que vai para a máquina.","items":{"enum":["HELENA","LAURA","AUGUSTO","MARINA","CAIO","CLARA","BIANCA","DANIEL","THEO","NINA","RAVI","MAYA","BRUNO","OLIVIA","VICTOR","CAMILA","ISABELA","PEDRO","RENATA","JOANA","FELIPE","FUNDADOR"]},"minItems":2,"type":"array","uniqueItems":true},"servico":{"pattern":"^SRV-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"}},"required":["id","servico","autor","revisores","depende_de"],"type":"object"},"item_do_pronto":{"additionalProperties":false,"allOf":[{"else":{"not":{"required":["checagem"]}},"if":{"properties":{"quem_confere":{"const":"CODIGO"}}},"then":{"required":["checagem"]}},{"else":{"not":{"required":["motivo_fundador"]}},"if":{"properties":{"quem_confere":{"const":"FUNDADOR"}}},"then":{"required":["motivo_fundador"]}}],"description":"Item do pronto do card (camada CARD; MEL-29). Toda restrição de ''nao_pode'' vira item de risco ALTO.","properties":{"checagem":{"description":"Obrigatória quando CODIGO: ID de checagem que já existe. A Helena não inventa checagem.","pattern":"^CHK-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"},"id":{"pattern":"^CARD-[1-5]$","type":"string"},"motivo_fundador":{"description":"Item seu só onde o plano já põe você; conferido no seu Aprovar, nunca como pergunta à parte.","enum":["ACAO_EXTERNA","JURIDICO","PLANO_DA_META"]},"quem_confere":{"enum":["CODIGO","IA","FUNDADOR"]},"risco":{"enum":["ALTO","BAIXO"]},"texto":{"maxLength":200,"minLength":3,"type":"string"}},"required":["id","texto","quem_confere","risco"],"type":"object"},"ordem_de_servico":{"additionalProperties":false,"description":"Ordem de serviço. Origem de cada campo (furo 6): empresa, prazo e prioridade vêm da caixa Novo pedido, gravados pelo código como toque seu ANTES de qualquer IA; pedido_original também. o_que_quer, como_e_o_pronto e nao_pode vêm da leitura de volta da Helena (no pedido grande, valem com o seu CONFIRMO); sem leitura (HELENA_FALHOU), o código preenche com o começo do seu pedido e com o pronto_padrao do serviço escolhido por você. O pedido original viaja inteiro por todas as etapas e revisões.","properties":{"como_e_o_pronto":{"items":{"$ref":"#/$defs/item_do_pronto"},"maxItems":5,"minItems":1,"type":"array"},"empresa":{"description":"Escolha obrigatória na caixa Novo pedido: BIZ-001 iGreen Energy, BIZ-002 Ecossistema de Saúde, BIZ-003 Humano Digital, BIZ-004 eLiving™, ou PESSOAL (só serviço da Laura; MAT-14). Nunca escolhida por IA. Decide o pacote que o agente recebe; pacote não CONFIRMADO dá PLANO_INVALIDO (MAT-23).","enum":["BIZ-001","BIZ-002","BIZ-003","BIZ-004","PESSOAL"]},"fontes_que_pode_ler":{"description":"Links do pedido que você ligou como ''pode ler'' (só https, sem consulta nem fragmento). Só estes entram na lista de ler_pagina, e ainda passam pelo acesso_sem_efeito (servicos.yaml, ferramentas_nossas).","items":{"maxLength":500,"pattern":"^https://[^\\s?#]+$","type":"string"},"maxItems":20,"type":"array","uniqueItems":true},"nao_pode":{"items":{"maxLength":200,"minLength":3,"type":"string"},"type":"array"},"o_que_quer":{"maxLength":400,"minLength":10,"type":"string"},"pedido_original":{"description":"Suas palavras, exatamente como chegaram (chave colada é trocada por ''[chave removida]'' antes de gravar).","maxLength":8000,"minLength":1,"type":"string"},"prazo":{"description":"Data e hora de Brasília (-03:00), da caixa Novo pedido. Se você não mexer, o código grava o padrão fixo (PROPOSTA: 3 dias corridos depois do pedido, às 18:00). Só você muda (botão MUDAR_PRAZO; regra 7); a sugestão da Helena vira item na sua lista. Cada mudança rearma os 3 avisos até TETO_MUDANCAS_PRAZO.","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?-03:00$","type":"string"},"prioridade":{"description":"1 = máxima. Da caixa Novo pedido; se você não mexer, o código grava o padrão fixo 3 (PROPOSTA). Só você muda (botão MUDAR_PRIORIDADE; regra 7).","maximum":5,"minimum":1,"type":"integer"}},"required":["empresa","prazo","prioridade","pedido_original"],"type":"object"},"plano":{"description":"Plano montado pelo código no VALIDANDO_PLANO e aprovado pelo validador (PLANO_VALIDO). null antes disso.","oneOf":[{"type":"null"},{"additionalProperties":false,"allOf":[{"else":{"not":{"required":["roteiro_id"]}},"if":{"properties":{"origem":{"const":"ROTEIRO"}}},"then":{"required":["roteiro_id"]}},{"if":{"properties":{"origem":{"const":"SERVICO_NAO_JULGADO"}}},"then":{"properties":{"etapas":{"maxItems":1}}}},{"if":{"properties":{"origem":{"const":"SERVICO_SEMPRE_JULGADO"}}},"then":{"properties":{"etapas":{"maxItems":2,"minItems":2}}}}],"properties":{"etapas":{"items":{"$ref":"#/$defs/etapa_do_plano"},"maxItems":12,"minItems":1,"type":"array"},"montado_em":{"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?-03:00$","type":"string"},"origem":{"description":"servicos.yaml, montagem_do_plano.","enum":["SERVICO_NAO_JULGADO","SERVICO_SEMPRE_JULGADO","ROTEIRO"]},"passos_fixos_do_fundador":{"items":{"additionalProperties":false,"properties":{"coberto_pelo_parecer":{"pattern":"^E[0-9]{1,2}$","type":"string"},"id":{"pattern":"^PF-[0-9]{2}$","type":"string"},"texto":{"maxLength":240,"minLength":5,"type":"string"}},"required":["id","texto","coberto_pelo_parecer"],"type":"object"},"type":"array"},"roteiro_id":{"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$","type":"string"},"versao_do_catalogo":{"maxLength":20,"minLength":1,"type":"string"}},"required":["origem","versao_do_catalogo","montado_em","etapas"],"type":"object"}]}},"$id":"helena-v2/card","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"allOf":[{"if":{"properties":{"estado":{"enum":["RASCUNHO","ESPERANDO_CONFIRMACAO","VALIDANDO_PLANO","EM_ANDAMENTO","ESPERANDO_FUNDADOR"]}}},"then":{"properties":{"fim":{"const":"NENHUM"}}}},{"if":{"properties":{"estado":{"const":"PRONTO"}}},"then":{"properties":{"fim":{"const":"CARD_PRONTO"}}}},{"if":{"properties":{"estado":{"const":"CANCELADO"}}},"then":{"properties":{"fim":{"enum":["PADRAO","FUNDADOR","SUBSTITUIDO"]}}}},{"if":{"properties":{"estado":{"const":"ENCERRADO_COM_FALHA"}}},"then":{"properties":{"fim":{"const":"FUNDADOR"}}}},{"if":{"properties":{"estado":{"enum":["RASCUNHO","VALIDANDO_PLANO","EM_ANDAMENTO"]}}},"then":{"properties":{"motivo":{"const":"NENHUM"}}}},{"if":{"properties":{"estado":{"const":"ESPERANDO_CONFIRMACAO"}}},"then":{"properties":{"motivo":{"enum":["NENHUM","HELENA_FALHOU","PLANO_INVALIDO","VALIDADOR_FALHOU"]}}}},{"if":{"properties":{"estado":{"const":"ESPERANDO_FUNDADOR"}}},"then":{"properties":{"motivo":{"enum":["DEPENDENCIA","NAO_PODE"]}}}},{"description":"Depois de PLANO_VALIDO o card sempre tem serviço ou roteiro escolhido e o plano montado, com os revisores efetivos de cada etapa.","if":{"properties":{"estado":{"enum":["EM_ANDAMENTO","ESPERANDO_FUNDADOR","PRONTO","ENCERRADO_COM_FALHA"]}}},"then":{"properties":{"escolha":{"properties":{"tipo":{"enum":["SERVICO","ROTEIRO"]}},"type":"object"},"plano":{"type":"object"}}}},{"if":{"properties":{"estado":{"const":"RASCUNHO"}}},"then":{"properties":{"escolha":{"type":"null"},"plano":{"type":"null"}}}},{"description":"Do ''Entendi assim'' em diante (ou do seu CONFIRMO sem leitura), a ordem de serviço está completa. Em RASCUNHO e com HELENA_FALHOU ela só tem os campos da caixa Novo pedido.","if":{"anyOf":[{"properties":{"estado":{"enum":["VALIDANDO_PLANO","EM_ANDAMENTO","ESPERANDO_FUNDADOR","PRONTO","ENCERRADO_COM_FALHA"]}}},{"properties":{"estado":{"const":"ESPERANDO_CONFIRMACAO"},"motivo":{"not":{"const":"HELENA_FALHOU"}}}}]},"then":{"properties":{"ordem_de_servico":{"required":["o_que_quer","como_e_o_pronto","nao_pode"]}}}},{"description":"Card PESSOAL só com serviço da Laura, e serviço da Laura só em card PESSOAL (MAT-14).","else":{"properties":{"escolha":{"not":{"properties":{"id":{"enum":["SRV-PLANO-DE-PRATICA"]},"tipo":{"const":"SERVICO"}},"required":["tipo","id"],"type":"object"}}}},"if":{"properties":{"ordem_de_servico":{"properties":{"empresa":{"const":"PESSOAL"}}}}},"then":{"properties":{"escolha":{"oneOf":[{"type":"null"},{"properties":{"id":{"enum":["SRV-PLANO-DE-PRATICA"]},"tipo":{"const":"SERVICO"}},"required":["tipo","id"],"type":"object"},{"properties":{"tipo":{"const":"FORA_DA_V2"}},"required":["tipo"],"type":"object"}]}}}},{"description":"FORA_DA_V2 sempre pede a sua confirmação (servicos.yaml, destino_fora_da_v2).","if":{"properties":{"escolha":{"properties":{"tipo":{"const":"FORA_DA_V2"}},"required":["tipo"],"type":"object"}},"required":["escolha"]},"then":{"properties":{"pedido_grande":{"const":true}}}},{"description":"Só o seu Cancelar com encaminhar_para_v1 encaminha; o padrão nunca encaminha.","if":{"properties":{"encaminhamento":{"type":"object"}},"required":["encaminhamento"]},"then":{"properties":{"estado":{"const":"CANCELADO"},"fim":{"const":"FUNDADOR"}}}},{"description":"Card nascido de um toque seu (ajuste depois de pronto, substituição no teto de ordens, resposta tardia com o card fechado) é sempre ligado ao anterior.","if":{"properties":{"id_mensagem_origem":{"properties":{"canal":{"const":"TOQUE_DO_FUNDADOR"}}}}},"then":{"properties":{"card_anterior":{"type":"object"}}}}],"description":"O card é a fonte única de cada trabalho. Estados, motivos e fins de maquina/vocabulario.yaml (versão 2.0.0); as passagens são as de maquina/passagens.yaml, aplicadas só pelo motor pela função única do banco. Contadores da máquina (ordens, perguntas, voltas, nível de prazo...) vivem na tabela do card e não são escritos aqui. Sem 👍/👎: o que você faz no card são os botões do vocabulário, gravados no histórico com o número único do toque e a versão vista.","properties":{"atualizado_em":{"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?-03:00$","type":"string"},"card_anterior":{"description":"Ligação com o card anterior: ajuste depois de pronto (card pronto não volta a andar; A-6), substituição no teto de ordens (passagens C17, C28, C29, C33) ou sua resposta depois de o card fechar.","oneOf":[{"type":"null"},{"additionalProperties":false,"properties":{"card_id":{"maxLength":80,"minLength":3,"type":"string"},"ligacao":{"enum":["AJUSTE_DEPOIS_DE_PRONTO","SUBSTITUICAO","RESPOSTA_TARDIA"]}},"required":["card_id","ligacao"],"type":"object"}]},"card_id":{"description":"Gerado pelo código, nunca pelo modelo.","maxLength":80,"minLength":3,"type":"string"},"criado_em":{"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?-03:00$","type":"string"},"decisoes_versao":{"description":"Versão das decisões vigentes lidas na hora; mudou, o que dependia é refeito (regra 10).","maxLength":80,"minLength":1,"type":"string"},"encaminhamento":{"description":"Pedido que a v2 ainda não atende e que você encaminhou à v1 (servicos.yaml, destino_fora_da_v2). null quando não houve.","oneOf":[{"type":"null"},{"additionalProperties":false,"properties":{"em":{"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?-03:00$","type":"string"},"id_toque":{"maxLength":80,"minLength":1,"type":"string"},"numero_v1":{"pattern":"^JOB-HR-[0-9a-f]{32}$","type":"string"},"para":{"const":"V1"}},"required":["para","numero_v1","em","id_toque"],"type":"object"}]},"escolha":{"description":"O que a Helena escolheu (ou você, no CONFIRMO com escolha); null enquanto o card é rascunho. O grafo é montado pelo código (servicos.yaml, montagem_do_plano).","oneOf":[{"type":"null"},{"additionalProperties":false,"properties":{"id":{"pattern":"^SRV-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"},"tipo":{"const":"SERVICO"}},"required":["tipo","id"],"type":"object"},{"additionalProperties":false,"properties":{"id":{"maxLength":80,"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$","type":"string"},"tipo":{"const":"ROTEIRO"}},"required":["tipo","id"],"type":"object"},{"additionalProperties":false,"properties":{"roteiro_que_atenderia":{"maxLength":80,"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$","type":"string"},"servico_que_atenderia":{"pattern":"^SRV-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"},"tipo":{"const":"FORA_DA_V2"}},"required":["tipo"],"type":"object"}]},"estado":{"enum":["RASCUNHO","ESPERANDO_CONFIRMACAO","VALIDANDO_PLANO","EM_ANDAMENTO","ESPERANDO_FUNDADOR","PRONTO","CANCELADO","ENCERRADO_COM_FALHA"]},"fim":{"enum":["PAI","PADRAO","PULADA","ENCERRAR_CARD","CARD_PRONTO","FUNDADOR","SUBSTITUIDO","FALHA","NENHUM"]},"id_mensagem_origem":{"additionalProperties":false,"description":"Número único da mensagem que criou o card, gravado pelo código ANTES de qualquer IA (A-8, B-16). O par canal+numero é único no banco: a mesma mensagem nunca vira dois cards.","properties":{"canal":{"enum":["APP","WHATSAPP","TOQUE_DO_FUNDADOR"]},"numero":{"maxLength":120,"minLength":1,"type":"string"}},"required":["canal","numero"],"type":"object"},"motivo":{"enum":["NENHUM","HELENA_FALHOU","PLANO_INVALIDO","VALIDADOR_FALHOU","DEPENDENCIA","NAO_PODE"]},"ordem_de_servico":{"$ref":"#/$defs/ordem_de_servico"},"pedido_grande":{"description":"Regra de código, nunca da IA sozinha (furo 6): true se você marcou ''confirmar antes'' na caixa Novo pedido; o código também marca true quando a escolha da Helena é ROTEIRO ou FORA_DA_V2 (só aumenta a confirmação, nunca diminui). É a guarda de C01/C02, gravada antes de a linha ser aplicada.","type":"boolean"},"plano":{"$ref":"#/$defs/plano"},"versao":{"description":"Versão que o app mostra; todo toque leva a versão vista e, se ela mudou, Aprovar, Pedir ajuste e Responder viram comentário.","minimum":1,"type":"integer"}},"required":["card_id","versao","id_mensagem_origem","ordem_de_servico","pedido_grande","escolha","plano","estado","motivo","fim","card_anterior","encaminhamento","decisoes_versao","criado_em"],"title":"Card (v3.1): ordem de serviço e estado","type":"object","x-regras-do-validador":["plano.etapas[].revisores termina em FUNDADOR e só tem agentes com aptidão APTA no tipo do serviço da etapa (MAT-21)","plano: toda etapa de serviço SEMPRE julgado está no ''julga'' de uma etapa SRV-PARECER do mesmo plano (MAT-22)","empresa da ordem de serviço está nas empresas de todos os serviços do plano e tem pacote CONFIRMADO (MAT-23)"]},"helena-v2/schemas/entrega.schema.json":{"$defs":{"checagem":{"additionalProperties":false,"description":"Checagem do portão 1, feita por código. Cada ID é estável e é o nome de uma função em helena-v2/checagens/ com caso bom e caso ruim (MEL-28). As checagens comuns (servicos.yaml, portao1_comum, CHK-COMUM-01 a 10) valem sempre e não se repetem aqui.","properties":{"descricao":{"maxLength":300,"minLength":10,"type":"string"},"fase":{"description":"Fase em que a função existe. ''fase 2'' = ID reservado até existir a ferramenta, o modelo de cálculo ou a tabela de leis.","enum":["fase 1","fase 2","fase 3"]},"fecha_furos":{"description":"Furo(s) que esta checagem fecha: IDs do registro (A-, B-, C-, K-, M-, FA-, FB-, FC-, R1-/R2-/R3-), da conferência v2 x v3 (CONF-nn), da prova da máquina (MAQ-nn) ou a decisão que ela garante (DEC-nnn).","items":{"pattern":"^((A|B|C|K|M)-[0-9]{1,3}|F[ABC]-[0-9]{1,2}|R[1-3]-[0-9]{2}|CONF-[0-9]{2}|MAQ-[0-9]{2}[a-z]?|DEC-[0-9]{3})$","type":"string"},"minItems":1,"type":"array","uniqueItems":true},"gravidade":{"description":"RECUSA = volta ao autor com o item exato; MARCA = segue com marca na faixa.","enum":["RECUSA","MARCA"]},"id":{"pattern":"^CHK-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"},"parametros":{"description":"Parâmetros fechados da checagem (ex.: lista de termos proibidos).","type":"object"}},"required":["id","descricao","fecha_furos","gravidade","fase"],"type":"object"},"criterio":{"additionalProperties":false,"description":"Critério da rubrica do revisor (portão 2; MEL-29). Só julgamento que o código não confere; nada de tamanho, seção, [Fn], HTML, idioma, termos de ganho, ''enviei/cadastrei''. Nenhum critério depende de lei, salvo na rubrica do próprio parecer: quem julga lei é só o parecer (MAT-22).","properties":{"evidencia_exigida":{"description":"TRECHO: o revisor cita o trecho literal que prova (o código confere que existe). AUSENCIA: algo que não pode estar. TEXTO_INTEIRO: tom, clareza, executável por leigo.","enum":["TRECHO","AUSENCIA","TEXTO_INTEIRO"]},"id":{"pattern":"^RUB-[A-Z0-9]+(-[A-Z0-9]+)*-[0-9]{2}$","type":"string"},"pergunta":{"description":"Pergunta verificável, que termina com ''?''.","maxLength":240,"minLength":10,"pattern":"\\?$","type":"string"},"por_que_o_codigo_nao_confere":{"maxLength":200,"minLength":5,"type":"string"},"risco":{"description":"Fixo no arquivo, nunca escolhido pelo revisor. NAO_CONSIGO_CONFERIR por estar fora do alcance: ALTO vira cartão de revisão para você; BAIXO segue marcado ''sem conferir'' na faixa.","enum":["ALTO","BAIXO"]},"vereditos":{"const":["PASSOU","FALHOU","NAO_CONSIGO_CONFERIR"]}},"required":["id","pergunta","evidencia_exigida","risco","por_que_o_codigo_nao_confere","vereditos"],"type":"object"},"entrada":{"additionalProperties":false,"properties":{"de_onde":{"enum":["PEDIDO_DO_CARD","ENTREGA_APROVADA","FONTE_IMPORTADA","DECISAO_VIGENTE","PACOTE_DA_EMPRESA","PAGINA_DA_LISTA","PASSOS_FIXOS_DO_ROTEIRO"]},"id":{"pattern":"^ENT-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"},"o_que":{"maxLength":200,"minLength":3,"type":"string"},"se_faltar":{"description":"Ação do autor quando falta (REGISTRAR_FALHA com motivo FALTAM_DADOS). Serviço com internet só pode REGISTRAR_FALHA (MAT-09).","enum":["PERGUNTAR","DEVOLVER_A_QUEM_PEDIU","REGISTRAR_FALHA"]}},"required":["id","o_que","de_onde","se_faltar"],"type":"object"},"pronto":{"additionalProperties":false,"description":"Critério de pronto em 3 camadas. A entrega só fica APROVADA com as 3 (e, no jurídico, com o seu Aprovar). Os itens CARD-n do card entram na camada código (se apontam para uma checagem existente) ou na rubrica (se são de IA).","properties":{"codigo":{"description":"IDs de checagens_codigo deste tipo (as comuns valem sempre).","items":{"pattern":"^CHK-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"},"type":"array","uniqueItems":true},"fundador":{"additionalProperties":false,"allOf":[{"if":{"properties":{"quando":{"not":{"const":"NUNCA"}}}},"then":{"required":["o_que_confere"]}}],"properties":{"o_que_confere":{"maxLength":300,"minLength":5,"type":"string"},"quando":{"description":"Você só entra no pronto onde o plano já põe você: ação externa (seu ok, uma vez) e jurídico (segundo revisor). Nenhum padrão automático aprova.","enum":["NUNCA","QUANDO_HA_ACAO_EXTERNA","SEMPRE_NO_JURIDICO"]}},"required":["quando"],"type":"object"},"rubrica":{"items":{"pattern":"^RUB-[A-Z0-9]+(-[A-Z0-9]+)*-[0-9]{2}$","type":"string"},"minItems":1,"type":"array","uniqueItems":true}},"required":["codigo","rubrica","fundador"],"type":"object"},"secao":{"additionalProperties":false,"allOf":[{"else":{"not":{"required":["colunas"]}},"if":{"properties":{"tipo_de_campo":{"const":"tabela"}}},"then":{"required":["colunas"]}},{"if":{"properties":{"tipo_de_campo":{"const":"numero"}}},"then":{"required":["unidade"]}},{"if":{"properties":{"tipo_de_campo":{"enum":["texto","numero","citacao"]}}},"then":{"not":{"anyOf":[{"required":["itens_min"]},{"required":["itens_max"]}]}}}],"properties":{"colunas":{"items":{"additionalProperties":false,"properties":{"apoiada_por_citacao":{"description":"Verdadeiro = o texto desta coluna é uma afirmação que a citação da mesma linha sustenta: CHK-COMUM-06 exige que os dois tenham ao menos uma palavra em comum. Tabela sem nenhuma coluna assim é só índice ou exemplo e não passa por essa conferência (a falta da citação, o trecho e o site continuam conferidos).","type":"boolean"},"descricao":{"maxLength":200,"minLength":1,"type":"string"},"id":{"pattern":"^[a-z][a-z0-9_]*$","type":"string"},"obrigatoria":{"description":"Falso = a coluna pode faltar na linha (o validador não recusa a falta). Sem o campo, a coluna é obrigatória. Se vier, o formato dela continua valendo.","type":"boolean"},"tipo_de_campo":{"enum":["texto","numero","citacao"]}},"required":["id","tipo_de_campo"],"type":"object"},"maxItems":12,"minItems":1,"type":"array"},"descricao":{"maxLength":300,"minLength":1,"type":"string"},"exige_citacao":{"description":"Cada item precisa de citação (CHK-COMUM-06).","type":"boolean"},"id":{"pattern":"^[a-z][a-z0-9_]*$","type":"string"},"itens_max":{"maximum":50,"minimum":1,"type":"integer"},"itens_min":{"minimum":0,"type":"integer"},"limite_caracteres":{"maximum":12000,"minimum":50,"type":"integer"},"obrigatoria":{"type":"boolean"},"tipo_de_campo":{"description":"Forma do valor na entrega (acao.schema.json, $defs valor_*): texto = texto puro; lista = itens de texto, cada um com citações quando a seção exigir fonte; tabela = linhas com as colunas declaradas; numero = valor com unidade e origem; citacao = trecho original apontando para a cópia guardada.","enum":["texto","lista","tabela","numero","citacao"]},"titulo":{"maxLength":80,"minLength":2,"type":"string"},"unidade":{"maxLength":30,"minLength":1,"type":"string"}},"required":["id","titulo","tipo_de_campo","obrigatoria"],"type":"object"},"tema":{"additionalProperties":false,"properties":{"como_conferir":{"maxLength":300,"minLength":5,"type":"string"},"id":{"pattern":"^TEMA-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"},"tema":{"maxLength":120,"minLength":3,"type":"string"}},"required":["id","tema","como_conferir"],"type":"object"}},"$id":"helena-v2/entrega","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"description":"Formato de um tipo de entrega (deliverables/<tipo>.yaml): seções tipadas, limite, checagens de código com ID, rubrica tipada do revisor e critério de pronto em 3 camadas. Cada tipo tem exatamente 1 dono e 1 serviço (servicos.yaml, MAT-02).","properties":{"checagens_codigo":{"items":{"$ref":"#/$defs/checagem"},"type":"array","uniqueItems":true},"criterio_de_pronto":{"$ref":"#/$defs/pronto"},"descricao":{"maxLength":300,"minLength":10,"type":"string"},"dono":{"description":"Uma das 21 identidades de vocabulario.identidades.agentes (sem acento, como o banco grava).","enum":["HELENA","LAURA","AUGUSTO","MARINA","CAIO","CLARA","BIANCA","DANIEL","THEO","NINA","RAVI","MAYA","BRUNO","OLIVIA","VICTOR","CAMILA","ISABELA","PEDRO","RENATA","JOANA","FELIPE"]},"entrada_minima":{"items":{"$ref":"#/$defs/entrada"},"minItems":1,"type":"array"},"limite":{"description":"Caracteres do conteúdo legível (CHK-COMUM-02).","maximum":12000,"minimum":500,"type":"integer"},"revisor_confere":{"description":"O que o revisor olha, em frases curtas (a rubrica é a forma verificável disso).","items":{"maxLength":240,"minLength":5,"type":"string"},"maxItems":10,"minItems":1,"type":"array"},"revisor_nao_reavalia":{"description":"O que o revisor NÃO julga (ex.: no relatório final, o mérito das entregas aprovadas).","items":{"maxLength":240,"minLength":5,"type":"string"},"type":"array"},"rubrica":{"items":{"$ref":"#/$defs/criterio"},"maxItems":8,"minItems":1,"type":"array"},"secoes":{"items":{"$ref":"#/$defs/secao"},"maxItems":15,"minItems":1,"type":"array"},"servico":{"pattern":"^SRV-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"},"temas_obrigatorios":{"description":"Quando o tipo tem tema que não pode faltar (ex.: parecer: imagem, voz, dado sensível, transferência para fora do país, menores, vínculo de trabalho, publicidade e os passos fixos do roteiro; C-10).","items":{"$ref":"#/$defs/tema"},"minItems":1,"type":"array"},"tipo":{"description":"Igual ao nome do arquivo.","pattern":"^[a-z][a-z0-9_]*$","type":"string"},"versao":{"pattern":"^3\\.1\\.[0-9]+$","type":"string"}},"required":["tipo","versao","descricao","dono","servico","secoes","limite","checagens_codigo","rubrica","criterio_de_pronto","revisor_confere","entrada_minima"],"title":"Tipo de entrega (v3.1)","type":"object","x-regras-do-validador":["dono e servico batem com servicos.yaml; arquivo = deliverables/<tipo>.yaml","ids de checagem e de rubrica únicos no repositório; cada CHK tem função com caso bom e caso ruim (MEL-28)","criterio_de_pronto.codigo e .rubrica só citam IDs deste arquivo; toda a rubrica está no pronto","critério de rubrica cujo texto repete uma checagem mecânica é recusado (lista fechada; MEL-29)","nenhum critério de rubrica depende de lei, em nenhum tipo, salvo no próprio parecer: quem julga lei é só o parecer (MAT-22); tipo SEMPRE julgado tem o parecer no mesmo card, e tipo sem parecer mostra ''sem conferência jurídica'' na faixa","tipo de serviço com ação do fundador: criterio_de_pronto.fundador.quando = QUANDO_HA_ACAO_EXTERNA","relatorio_final: revisor_nao_reavalia é obrigatório e repete a regra_do_relatorio_final de servicos.yaml (fidelidade e linguagem; nunca o mérito, nem da própria entrega)","parecer: temas_obrigatorios é obrigatório (imagem, voz, dado sensível, transferência para fora do país, menores, vínculo de trabalho, publicidade e os passos fixos do roteiro; C-10); entrada_minima tem PACOTE_DA_EMPRESA e PASSOS_FIXOS_DO_ROTEIRO","serviço com internet (servicos.yaml usa_internet) só usa se_faltar = REGISTRAR_FALHA em entrada_minima (MAT-09)"]},"helena-v2/schemas/plano.schema.json":{"$id":"helena-v2/plano","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"properties":{"card_id":{"type":"string"},"etapas":{"items":{"additionalProperties":false,"properties":{"depende_de":{"items":{"pattern":"^E[0-9]{1,2}$","type":"string"},"type":"array"},"dividir_por":{"description":"Itens independentes (ex.: plataformas); o motor cria uma sub-etapa por item","items":{"type":"string"},"type":"array"},"entradas":{"description":"IDs de etapas ou de entregas aprovadas","items":{"type":"string"},"type":"array"},"entrega":{"pattern":"^[a-z_]+$","type":"string"},"id":{"pattern":"^E[0-9]{1,2}$","type":"string"},"objetivo":{"maxLength":350,"type":"string"},"responsavel":{"pattern":"^AGT-[0-9]{2}$","type":"string"}},"required":["id","responsavel","entrega","objetivo","depende_de"],"type":"object"},"maxItems":12,"minItems":1,"type":"array"},"meta":{"maxLength":300,"type":"string"},"precisa_ok_fundador":{"description":"O motor forca true se houver mais de 6 etapas, gasto, ato externo ou prazo acima de 7 dias","type":"boolean"}},"required":["card_id","meta","etapas"],"title":"Plano como dado (proposto pela Helena, validado pelo codigo antes de executar)","type":"object","x-validacoes-do-motor":["responsavel existe, esta ativo e tem a entrega em ''produz''","dependencias existem e nao formam ciclo","entradas apontam para etapas anteriores ou entregas aprovadas","tamanho estimado cabe no modelo da entrega; senao exige dividir_por","orcamento total do card nao excede o limite da meta","pesquisa (entrega dossie) respeita a cota de pesquisa da meta"]},"helena-v2/schemas/playbook.schema.json":{"$defs":{"etapa":{"additionalProperties":false,"allOf":[{"else":{"not":{"required":["se_semaforo"]}},"if":{"required":["julga"]},"then":{"required":["se_semaforo"]}}],"description":"Uma etapa do roteiro. Quem faz é o DONO do serviço; revisor e reserva NÃO se escrevem aqui: o código calcula os revisores efetivos do catálogo (servicos.yaml, MAT-21) e a tabela põe você como última reserva. Ferramentas, internet e ações também vêm do serviço.","properties":{"depende_de":{"items":{"pattern":"^E[0-9]{1,2}$","type":"string"},"type":"array","uniqueItems":true},"dividir_por":{"description":"Divisão só a declarada no roteiro (MEL-24).","items":{"maxLength":80,"minLength":1,"type":"string"},"minItems":2,"type":"array"},"entradas":{"description":"Ids de etapas anteriores (das quais depende) ou nomes de entradas_externas.","items":{"minLength":2,"type":"string"},"type":"array","uniqueItems":true},"id":{"pattern":"^E[0-9]{1,2}$","type":"string"},"julga":{"description":"Só na etapa do SRV-PARECER (a julgadora): etapas que ela julga; precisa depender delas, e o tipo de cada uma precisa estar em julga_tipos (MAT-07).","items":{"pattern":"^E[0-9]{1,2}$","type":"string"},"minItems":1,"type":"array","uniqueItems":true},"objetivo":{"maxLength":350,"minLength":10,"type":"string"},"prazo_de_terceiro":{"default":false,"description":"A etapa depende de prazo de terceiro declarado aqui: a pergunta dela vira espera EXTERNA (um lembrete antes do prazo e depois o padrão). Nunca é escolha do agente (E21/E120).","type":"boolean"},"pulavel":{"default":false,"description":"''Seguir sem'' só se o roteiro permitir; nunca no parecer, no relatório final, numa etapa julgada nem em serviço SEMPRE julgado (MEL-24; servicos.yaml pode_ser_pulada).","type":"boolean"},"se_semaforo":{"additionalProperties":false,"description":"Só na julgadora. O parecer só vale com o seu Aprovar (passagens.yaml E74, E81-E83).","properties":{"AJUSTE":{"additionalProperties":false,"properties":{"max_ciclos":{"const":2,"description":"Igual a passagens.yaml tetos.TETO_VOLTAS_JURIDICO (2): depois da 2ª volta, a etapa vai para em resolução (E83)."},"refazer":{"description":"Igual a ''julga'': o sinal AJUSTE_DO_JULGADOR vai a todas as julgadas abertas, e a julgadora refaz sobre o texto novo.","items":{"pattern":"^E[0-9]{1,2}$","type":"string"},"minItems":1,"type":"array","uniqueItems":true}},"required":["refazer","max_ciclos"],"type":"object"},"NAO_PODE":{"additionalProperties":false,"properties":{"aguardar_fundador":{"const":true,"description":"O card pergunta a você (passagens.yaml C14)."}},"required":["aguardar_fundador"],"type":"object"}},"required":["AJUSTE","NAO_PODE"],"type":"object"},"servico":{"pattern":"^SRV-[A-Z0-9]+(-[A-Z0-9]+)*$","type":"string"},"usa_decisao":{"default":true,"description":"Decisão nova sua refaz esta etapa (regra 10).","type":"boolean"}},"required":["id","servico","objetivo","entradas","depende_de"],"type":"object"}},"$id":"helena-v2/playbook","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"description":"Meta conhecida -> etapas, cada uma por SERVIÇO do catálogo. O código monta o plano (MEL-24; servicos.yaml, montagem_do_plano), grava-o no card e o converte no roteiro que a máquina lê (maquina/jornada.schema.json): autor = dono do serviço; revisores = os revisores EFETIVOS do serviço, isto é, [revisor, reserva] só com aptidão APTA no tipo, e FUNDADOR no fim (MAT-21); internet = usa_internet do serviço; acoes_permitidas = as do serviço; julga, pulavel, prazo_de_terceiro e usa_decisao copiados daqui. Empresa, prioridade e prazo do card são seus (caixa Novo pedido), não do roteiro.","properties":{"acoes_do_fundador":{"description":"Ação do fundador que cada etapa pode propor, com o texto fixo escrito por você (é ele que aparece na sua lista, nunca texto da IA). Nasce como proposta só quando o card fica PRONTO (E110), no máximo uma por etapa; o motor nunca executa sem o seu ok registrado.","items":{"additionalProperties":false,"properties":{"acao_do_fundador":{"enum":["AF-ADMIN-PAGAR-RENOVAR-ASSINAR","AF-PESSOAS-PUBLICAR-VAGA","AF-TECNICA-CONTRATAR-SERVICO","AF-CAMPANHA-LANCAR","AF-COPY-ENVIAR-OU-PUBLICAR","AF-TREINAMENTO-ENVIAR","AF-VENDAS-CONTATAR","AF-PARCERIA-CONTATAR","AF-SUCESSO-FALAR-COM-CLIENTE","AF-ATENDIMENTO-ENVIAR-RESPOSTA"]},"descricao":{"maxLength":240,"minLength":5,"type":"string"},"etapa":{"pattern":"^E[0-9]{1,2}$","type":"string"}},"required":["etapa","acao_do_fundador","descricao"],"type":"object"},"type":"array"},"decisoes":{"description":"Decisões que o código injeta (texto vigente lido na hora) e grava em cada execução.","items":{"pattern":"^DEC-[0-9]{3}$","type":"string"},"type":"array","uniqueItems":true},"empresas":{"description":"Empresas para as quais o roteiro serve; cada uma precisa estar nas empresas de todos os serviços dele e ter pacote CONFIRMADO para rodar (MAT-23).","items":{"enum":["BIZ-001","BIZ-002","BIZ-003","BIZ-004"]},"minItems":1,"type":"array","uniqueItems":true},"entradas_externas":{"additionalProperties":{"pattern":"^JOB-HR-[0-9a-f]{32}$","type":"string"},"description":"Entregas aprovadas da v1, importadas com cópia antes da execução.","propertyNames":{"pattern":"^[a-z][a-z0-9_]*$"},"type":"object"},"etapas":{"items":{"$ref":"#/$defs/etapa"},"maxItems":12,"minItems":1,"type":"array"},"id":{"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$","type":"string"},"nome":{"maxLength":120,"minLength":5,"type":"string"},"orcamento_meta":{"additionalProperties":false,"description":"Teto da meta inteira, somando todos os agentes, em chamadas (não em passos). O validador confere que a soma das fichas das etapas cabe aqui (furo 9).","properties":{"buscas":{"description":"Zero enquanto ''buscar'' não existe (até a fase 4; MEL-34).","minimum":0,"type":"integer"},"chamadas_total":{"minimum":1,"type":"integer"},"execucoes":{"description":"Execuções de agente (autor, revisor e Helena), dentro do orçamento diário de models.yaml.","minimum":1,"type":"integer"},"partes_de_pagina":{"minimum":0,"type":"integer"}},"required":["chamadas_total","buscas","partes_de_pagina","execucoes"],"type":"object"},"passos_fixos_do_fundador":{"description":"Passos externos do roteiro que não são entrega de nenhum agente (ex.: cadastrar a empresa numa plataforma). Texto fixo seu; aparecem na lista do que só você faz, marcados ''passo fixo do roteiro''; nunca são executados pelo motor e não viram proposta da máquina de ação externa. Cada um é tema obrigatório do parecer que o cobre (OK ou NÃO PODE).","items":{"additionalProperties":false,"properties":{"categorias":{"items":{"enum":["CADASTRO","CONTATO","GASTO","CONTRATO","PUBLICACAO"]},"maxItems":2,"minItems":1,"type":"array","uniqueItems":true},"coberto_pelo_parecer":{"description":"A etapa SRV-PARECER do roteiro que julga este passo.","pattern":"^E[0-9]{1,2}$","type":"string"},"id":{"pattern":"^PF-[0-9]{2}$","type":"string"},"texto":{"maxLength":240,"minLength":5,"type":"string"}},"required":["id","texto","categorias","coberto_pelo_parecer"],"type":"object"},"type":"array"},"prazo_sugerido_dias":{"description":"Só sugestão para o ''Entendi assim''; o prazo do card é o seu.","maximum":90,"minimum":1,"type":"integer"},"versao":{"pattern":"^3\\.1\\.[0-9]+$","type":"string"}},"required":["id","versao","nome","empresas","decisoes","orcamento_meta","etapas","acoes_do_fundador","passos_fixos_do_fundador"],"title":"Roteiro de meta (v3.1)","type":"object","x-regras-do-validador":["todo serviço existe no catálogo e está em ESTAGIO ou ATIVO, com o dono ligado, para o roteiro rodar na v2 (senão o pedido vai para o destino_fora_da_v2; A-12)","empresas do roteiro estão nas empresas de cada serviço e têm pacote CONFIRMADO; nenhum serviço PESSOAL (MAT-14, MAT-23)","depende_de e entradas apontam para etapas existentes; entrada de etapa exige dependência; sem ciclo","exatamente 1 etapa do SRV-RELATORIO-FINAL, a última, dependendo de todas as outras (MAT-15)","etapa do SRV-PARECER tem ''julga'' só com etapas cujo tipo está em julga_tipos, e depende delas (MAT-07); refazer = julga","etapa do SRV-PARECER só recebe como entrada etapas que ela julga, etapas SRV-DOSSIE e entradas externas (MAT-05)","toda etapa de serviço SEMPRE julgado (com ação do fundador) está no ''julga'' de uma etapa SRV-PARECER (MAT-22)","nenhuma etapa SRV-COPY tem como entrada uma etapa SRV-CALCULO (MAT-16; C-11)","pulavel só onde o serviço permite (pode_ser_pulada) e nunca em etapa julgada","acoes_do_fundador: etapa existe, no máximo uma por etapa, o id está na lista do serviço dela, e nunca numa etapa SRV-RELATORIO-FINAL (MAT-11)","passos_fixos_do_fundador: coberto_pelo_parecer aponta para uma etapa SRV-PARECER do roteiro; sem parecer no roteiro, não há passo fixo","toda etapa tem pelo menos um revisor de IA com aptidão APTA (MAT-21)","soma dos orçamentos das fichas cabe em orcamento_meta"]},"helena-v2/servicos.yaml":{"acoes_do_autor_liberaveis":["ENTREGAR","PERGUNTAR","DEVOLVER_A_QUEM_PEDIU","REGISTRAR_FALHA"],"agentes":{"AUGUSTO":{"ficha":"agents/augusto.yaml","id":"AGT-03","possui":{"analise_estrategica":"deliverables/analise_estrategica.yaml"},"revisa":{"dossie":"SEM_PROVA","perfil_de_funcao":"SEM_PROVA","plano_de_campanha":"SEM_PROVA","plano_de_projeto":"SEM_PROVA","tese_de_parceria":"SEM_PROVA"}},"BIANCA":{"ficha":"agents/bianca.yaml","id":"AGT-07","possui":{"perfil_de_funcao":"deliverables/perfil_de_funcao.yaml"},"revisa":{}},"BRUNO":{"ficha":"agents/bruno.yaml","id":"AGT-13","possui":{"plano_de_testes":"deliverables/plano_de_testes.yaml"},"revisa":{"especificacao_de_interface":"SEM_PROVA","proposta_tecnica":"SEM_PROVA"}},"CAIO":{"ficha":"agents/caio.yaml","id":"AGT-05","possui":{"calculo":"deliverables/calculo.yaml"},"revisa":{"analise_de_dados":"SEM_PROVA","analise_estrategica":"SEM_PROVA","copy":"APTA","relatorio_final":"APTA","roteiro_treinamento":"APTA"}},"CAMILA":{"ficha":"agents/camila.yaml","id":"AGT-16","possui":{"plano_de_campanha":"deliverables/plano_de_campanha.yaml"},"revisa":{"copy":"SEM_PROVA","roteiro_comercial":"SEM_PROVA"}},"CLARA":{"ficha":"agents/clara.yaml","id":"AGT-06","possui":{"parecer":"deliverables/parecer.yaml"},"revisa":{"calculo":"APTA","relatorio_final":"APTA"}},"DANIEL":{"ficha":"agents/daniel.yaml","id":"AGT-08","possui":{"analise_de_dados":"deliverables/analise_de_dados.yaml"},"revisa":{"plano_de_campanha":"SEM_PROVA","plano_de_sucesso":"SEM_PROVA"}},"FELIPE":{"ficha":"agents/felipe.yaml","id":"AGT-21","possui":{"controle_administrativo":"deliverables/controle_administrativo.yaml"},"revisa":{"plano_de_projeto":"SEM_PROVA","procedimento_operacional":"SEM_PROVA"}},"HELENA":{"ficha":"agents/helena.yaml","id":"AGT-01","possui":{"relatorio_final":"deliverables/relatorio_final.yaml"},"revisa":{"calculo":"APTA","parecer":"APTA","plano_de_pratica":"SEM_PROVA"}},"ISABELA":{"ficha":"agents/isabela.yaml","id":"AGT-17","possui":{"copy":"deliverables/copy.yaml","roteiro_treinamento":"deliverables/roteiro_treinamento.yaml"},"revisa":{"dossie":"SEM_PROVA","rascunho_de_resposta":"SEM_PROVA","roteiro_comercial":"SEM_PROVA"}},"JOANA":{"ficha":"agents/joana.yaml","id":"AGT-20","possui":{"rascunho_de_resposta":"deliverables/rascunho_de_resposta.yaml"},"revisa":{}},"LAURA":{"ficha":"agents/laura.yaml","id":"AGT-02","possui":{"plano_de_pratica":"deliverables/plano_de_pratica.yaml"},"revisa":{}},"MARINA":{"ficha":"agents/marina.yaml","id":"AGT-04","possui":{"plano_de_projeto":"deliverables/plano_de_projeto.yaml"},"revisa":{"controle_administrativo":"SEM_PROVA","procedimento_operacional":"SEM_PROVA"}},"MAYA":{"ficha":"agents/maya.yaml","id":"AGT-12","possui":{"especificacao_de_interface":"deliverables/especificacao_de_interface.yaml"},"revisa":{"requisitos_de_produto":"SEM_PROVA"}},"NINA":{"ficha":"agents/nina.yaml","id":"AGT-10","possui":{"requisitos_de_produto":"deliverables/requisitos_de_produto.yaml"},"revisa":{"especificacao_de_interface":"SEM_PROVA","plano_de_testes":"SEM_PROVA","proposta_tecnica":"SEM_PROVA"}},"OLIVIA":{"ficha":"agents/olivia.yaml","id":"AGT-14","possui":{"procedimento_operacional":"deliverables/procedimento_operacional.yaml"},"revisa":{"controle_administrativo":"SEM_PROVA","perfil_de_funcao":"SEM_PROVA","roteiro_treinamento":"SEM_PROVA"}},"PEDRO":{"ficha":"agents/pedro.yaml","id":"AGT-18","possui":{"tese_de_parceria":"deliverables/tese_de_parceria.yaml"},"revisa":{}},"RAVI":{"ficha":"agents/ravi.yaml","id":"AGT-11","possui":{"dossie":"deliverables/dossie.yaml"},"revisa":{"analise_de_dados":"SEM_PROVA","analise_estrategica":"SEM_PROVA","requisitos_de_produto":"SEM_PROVA"}},"RENATA":{"ficha":"agents/renata.yaml","id":"AGT-19","possui":{"plano_de_sucesso":"deliverables/plano_de_sucesso.yaml"},"revisa":{"rascunho_de_resposta":"SEM_PROVA"}},"THEO":{"ficha":"agents/theo.yaml","id":"AGT-09","possui":{"proposta_tecnica":"deliverables/proposta_tecnica.yaml"},"revisa":{"plano_de_testes":"SEM_PROVA"}},"VICTOR":{"ficha":"agents/victor.yaml","id":"AGT-15","possui":{"roteiro_comercial":"deliverables/roteiro_comercial.yaml"},"revisa":{"plano_de_sucesso":"SEM_PROVA","tese_de_parceria":"SEM_PROVA"}}},"aptidao_de_revisao":{"como_fica_apta":"Teste 9 do par revisor x tipo (MEL-41): pega pelo menos 3 de 5 erros plantados daquele tipo e recusa no máximo 2 de 5 entregas limpas; nos tipos de risco alto, cada erro é pego em pelo menos 2 de 3 rodadas; com a versão atual da rubrica do tipo. Depois, o seu toque. Só vale para agente já ligado (o passo dele na ordem_de_ativacao já foi feito).","designavel":["APTA"],"estados":{"APTA":"Passou no teste 9 daquele par e você tocou em ''ligar''. Pode ser designado.","PAUSADA":"Você desligou. Não é designado em plano novo; as revisões já designadas a ele terminam com ele.","SEM_PROVA":"O par (agente, tipo) nunca passou no teste de revisão daquele tipo com a rubrica atual. Nunca é designado."},"quem_muda":"Só você. O disjuntor nunca mexe em aptidão. Pausar o serviço de autor de um agente não mexe nas aptidões de revisão dele.","rubrica_mudou":"Mudar a rubrica de um tipo faz as aptidões daquele tipo exigirem o teste 9 de novo antes de qualquer plano novo; as revisões já designadas terminam."},"capacidade":{"agentes_ao_mesmo_tempo":3,"regra":"Falta de vaga nunca troca autor nem revisor e nunca gera evento na máquina: a etapa espera a vaga do designado, na ordem da prioridade do card (só você muda) e da chegada.","vaga_da_helena":"A Helena tem 1 vaga própria de coordenação (leitura de volta e recomendação), separada da vaga de trabalho (relatório e revisões): as suas mensagens nunca esperam atrás de uma revisão."},"categorias_de_acao_externa":["CADASTRO","CONTATO","GASTO","CONTRATO","PUBLICACAO"],"coordenacao_da_helena":{"LER_DE_VOLTA":"Só lê o pedido e escolhe: 1 serviço escolhível que recebe card, 1 roteiro, ou FORA_DA_V2 (com o serviço que atenderia, quando houver). Escreve o que entendeu (o que você quer, como é o pronto, o que não pode) e pode sugerir um prazo, que vira item na sua lista. Nunca escolhe empresa, prioridade nem prazo do card (vêm da caixa Novo pedido). Não faz pergunta de opções A/B/C: em caso de dúvida, você confirma com outra escolha da lista do app.","RECOMENDAR":"Numa etapa em resolução, escolhe uma opção da lista fechada: REFAZER, SEGUIR_SEM ou ENCERRAR. Não replaneja nem divide etapa (MEL-24). Não é chamada quando participou da peça (MAT-26).","SUGERIR_PRAZO":"Vira item na sua lista. O prazo só muda pelo seu botão."},"destino_fora_da_v2":{"caminho_na_maquina":"FORA_DA_V2 sempre marca o card como pedido grande (o código só aumenta a confirmação, nunca diminui): C01 leva a ESPERANDO_CONFIRMACAO e o app mostra ''Isto ainda não está na v2: quem atenderia é <serviço>''. Recusa do validador leva a ESPERANDO_CONFIRMACAO com PLANO_INVALIDO (C11).","o_que_voce_pode_fazer":["Encaminhar à v1: botão CANCELAR com encaminhar_para_v1 (C22). O código cria o trabalho na v1 com o seu pedido original, grava o número dele no card (encaminhamento) e mostra a você. Um sistema por pedido (A-12).","Confirmar com outro serviço ou roteiro da lista do app: RESPONDER CONFIRMO com escolha (C06).","Cancelar sem encaminhar: CANCELAR."],"quando":"A Helena devolve a escolha FORA_DA_V2 (o serviço que atenderia ainda não recebe card, ou nenhum serviço atende), ou o validador do plano recusa pela empresa ou pelo estado do serviço.","sem_resposta":"Lembrete em 24 h e 48 h e depois o padrão (C07-C09): o card fecha CANCELADO com fim PADRAO e marcado ''não encaminhado''. O padrão nunca encaminha nem aprova."},"estado_da_coordenacao":{"pausada":"Card novo: a leitura de volta não roda; o relógio leva o rascunho a você em 15 min (C05, HELENA_FALHOU). Etapa em resolução: o cartão chega a você sem recomendação (E101).","quem_muda":"Só você (e PAUSAR_TUDO). O disjuntor nunca pausa a coordenação. Pausar o SRV-RELATORIO-FINAL não mexe na coordenação nem nas aptidões de revisão da Helena.","vale_para":"Respostas do papel HELENA: LER_DE_VOLTA e RECOMENDAR.","valores":["ATIVA","PAUSADA"]},"estados_do_servico":{"APOSENTADO":"Saiu do cardápio; nenhum card novo.","ATIVO":"Recebe card real normalmente.","EM_TESTE":"Rodando a bateria de casos (camada A e B). Não recebe card real.","ESTAGIO":"Recebe card real pela tela nova, com a faixa ''em estágio: x de 5'' e você como revisor a mais.","PAUSADO":"Parado por você ou pelo disjuntor (3 falhas seguidas do agente COMO AUTOR deste serviço). Pedidos novos não entram. Não mexe nas aptidões de revisão do agente nem na coordenação da Helena.","RASCUNHO":"Especificado, sem casos aprovados. Não recebe card na v2."},"fases":["v2.0","fase 3","fase 4"],"ferramentas_nossas":{"buscar":{"desde":"fase 4","efeito":"LER","o_que_faz":"Busca aberta. Só na fase 4, depois de você escolher o serviço de busca e o custo (MEL-34). Os resultados passam pelas mesmas regras de acesso de ler_pagina."},"ler_pagina":{"acesso_sem_efeito":["Só leitura (GET), sem cookie, sem login, sem formulário e sem executar código da página.","Antes de entrar na lista, o código tira consulta (?...) e fragmento (#...) do endereço; endereço que só funciona com eles fica fora.","Recusa caminho de ação: confirmar, confirm, verificar, verify, aceitar, accept, convite, invite, indicacao, ref, descadastrar, unsubscribe, token, login, signin, signup, cadastro, register, checkout, pagar, pay.","Não segue redirecionamento para outro domínio; no mesmo domínio, no máximo 3, cada um passando pelas mesmas regras.","Cada acesso fica registrado (endereço, hora, tamanho e cópia guardada).","Fora disso, a resposta é ''fonte insuficiente'' e o acesso não acontece."],"desde":"fase 3","efeito":"LER","lista":"Fontes que você aprovou: links que você ligou como ''pode ler'' na caixa Novo pedido (ou na leitura de volta), fontes importadas aprovadas, termos das plataformas e a tabela de leis. Link colado no pedido sem o seu ''pode ler'' NÃO entra.","o_que_faz":"Lê uma página da lista montada pelo código, em partes de até 20 mil caracteres. Fora da lista: ''fonte insuficiente'' (MEL-34)."}},"fonte_dos_nomes":"maquina/vocabulario.yaml","fora_do_catalogo":[{"destino":"O motor e o relógio do banco, pela tabela de passagens (neutro: DBOS ou motor próprio). Por isso a Marina não acompanha nem move cards.","dono":"MOTOR","id":"FORA-COORDENACAO","o_que":"Coordenar cards e etapas: fila, dependências, prazos, avisos e designação do revisor.","prazo":"Permanente (decisão de desenho)."},{"destino":"Contador contratado por você; enquanto isso, a v1. O Caio faz conta e cenário, não fechamento nem imposto.","dono":"FUNDADOR","id":"FORA-FISCAL-CONTABIL","o_que":"Imposto, nota fiscal, enquadramento e fechamento contábil.","prazo":"Decidir no portão da fase 4 se vira serviço próprio (com tipo, dono, revisor e fase)."},{"destino":"Advogado; enquanto isso, a v1. Na v2, o parecer da Clara julga só peças do card e os passos fixos do roteiro (o cadastro na Mimix e no Hub é julgado assim, na primeira meta).","dono":"FUNDADOR","id":"FORA-CONTRATOS-E-PRIVACIDADE","o_que":"Revisar contrato que você recebeu, termos de uso, política de privacidade ou outro documento seu, sem peça do card para julgar.","prazo":"Decidir no portão da fase 4 se a Clara ganha ''parecer sobre documento seu'' (precisa de linha nova na tabela para você ser o segundo revisor sem etapa julgada)."},{"destino":"Você escreve e registra como decisão. Hoje confirmados: Humano Digital (BIZ-003) e eLiving™ (BIZ-004).","dono":"FUNDADOR","id":"FORA-PACOTE-DE-VOZ","o_que":"Escrever a voz e as proibições de cada empresa (o ''pacote'' que o agente recebe com o card).","prazo":"iGreen (BIZ-001) e Ecossistema de Saúde (BIZ-002): antes de qualquer serviço atender essas empresas; no mais tardar, no portão da fase 4. Até lá, card delas dá PLANO_INVALIDO com o motivo, e você pode encaminhar à v1."},{"destino":"Ninguém na v2.0: o tipo da mensagem vem do botão do app (MEL-25).","dono":"FUNDADOR","id":"FORA-CLASSIFICAR-MENSAGEM","o_que":"Classificar mensagem livre.","prazo":"Permanente na v2.0."},{"destino":"O código materializa na tabela de destino, fora da esteira de agentes. Nenhum agente grava em tabela.","dono":"FUNDADOR","id":"FORA-COMANDOS-DIRETOS","o_que":"Seus comandos diretos de criar empresa, conta ou outra entidade (DEC-022).","prazo":"Permanente."},{"destino":"Nenhum agente. A central da v1 será desligada (sua decisão de 10/10/2026); a Joana só escreve o rascunho, que você envia.","dono":"FUNDADOR","id":"FORA-RESPONDER-CLIENTE","o_que":"Responder cliente, ligar para alguém, URA.","prazo":"Permanente."},{"destino":"Desligado (MEL-24).","dono":"FUNDADOR","id":"FORA-SUBCARD","o_que":"Pedir sub-card.","prazo":"Fase 4, com decisão sua."},{"destino":"Personagens do produto eLiving™, não funcionários. Ficam fora do organograma e deste catálogo.","dono":"FUNDADOR","id":"FORA-PERSONAGENS","o_que":"Sirlene, Doutor Vital, Alex e Rafael.","prazo":"Permanente."}],"mapa_de_areas":[{"area":"Estratégia do negócio","atende":"SRV-ANALISE-ESTRATEGICA"},{"area":"Projetos e cronogramas para você","atende":"SRV-PLANO-DE-PROJETO"},{"area":"Finanças: conta, caixa, custo, margem, cenários","atende":"SRV-CALCULO"},{"area":"Fiscal e contábil: imposto, nota, fechamento","atende":"FORA-FISCAL-CONTABIL"},{"area":"Dados e indicadores","atende":"SRV-ANALISE-DE-DADOS"},{"area":"Administração: documentos, fornecedores, vencimentos","atende":"SRV-CONTROLE-ADMINISTRATIVO"},{"area":"Jurídico das peças do card (antes de agir)","atende":"SRV-PARECER"},{"area":"Contratos, termos de uso e privacidade de documento seu","atende":"FORA-CONTRATOS-E-PRIVACIDADE"},{"area":"Pesquisa com fontes","atende":"SRV-DOSSIE"},{"area":"Pessoas: funções, vagas, desempenho","atende":"SRV-PERFIL-DE-FUNCAO"},{"area":"Produto: problema e requisitos","atende":"SRV-REQUISITOS-DE-PRODUTO"},{"area":"Design de telas","atende":"SRV-ESPECIFICACAO-DE-INTERFACE"},{"area":"Tecnologia","atende":"SRV-PROPOSTA-TECNICA"},{"area":"Testes de produto e software","atende":"SRV-PLANO-DE-TESTES"},{"area":"Marketing: campanhas e experimentos","atende":"SRV-PLANO-DE-CAMPANHA"},{"area":"Texto pronto: convite, anúncio, mensagem","atende":"SRV-COPY"},{"area":"Treinamento de pessoa leiga de fora (participante, cliente)","atende":"SRV-ROTEIRO-TREINAMENTO"},{"area":"Marca: pacote de voz e proibições de cada empresa","atende":"FORA-PACOTE-DE-VOZ"},{"area":"Vendas: abordagem um a um e funil","atende":"SRV-ROTEIRO-COMERCIAL"},{"area":"Parcerias","atende":"SRV-TESE-DE-PARCERIA"},{"area":"Sucesso e retenção de clientes","atende":"SRV-PLANO-DE-SUCESSO"},{"area":"Atendimento: resposta a uma solicitação","atende":"SRV-RASCUNHO-DE-RESPOSTA"},{"area":"Operação: rotina interna","atende":"SRV-PROCEDIMENTO-OPERACIONAL"},{"area":"Seu desenvolvimento pessoal","atende":"SRV-PLANO-DE-PRATICA"},{"area":"Coordenar cards e etapas","atende":"FORA-COORDENACAO"}],"montagem_do_plano":{"FORA_DA_V2":"Nenhum plano: o card mostra o destino_fora_da_v2.","ROTEIRO":"As etapas do roteiro escolhido (playbooks/<id>.yaml), validadas pelas regras do playbook.schema.json.","SERVICO_NAO_JULGADO":"Uma etapa só: E1 = o serviço escolhido.","SERVICO_SEMPRE_JULGADO":"Grafo fixo de duas etapas (furo 2): E1 = o serviço escolhido; E2 = SRV-PARECER, julga [E1], depende de [E1], entradas [E1] e o pacote da empresa, se_semaforo AJUSTE refazer [E1] com max_ciclos 2 e NAO_PODE aguardar você. Você é o segundo revisor do parecer (E74).","o_motivo_aparece":"O card mostra o motivo exato da recusa em linguagem simples (C11).","validador_do_plano_recusa":["Escolha ausente ou FORA_DA_V2.","Serviço fora de ESTAGIO/ATIVO agora, ou cujo dono ainda não foi ligado.","Empresa do card fora das empresas de algum serviço do plano, ou com pacote não CONFIRMADO (MAT-23).","Card PESSOAL com serviço de empresa, ou card de empresa com serviço PESSOAL (MAT-14).","Etapa de serviço SEMPRE julgado sem etapa SRV-PARECER que a julgue no mesmo plano (MAT-22).","Etapa cuja lista de revisores efetivos fica só com FUNDADOR (MAT-21).","Ação do fundador fora da lista do serviço da etapa, ação do fundador no relatório, ou passo fixo sem parecer que o cubra (MAT-11).","Entrada do SRV-PARECER que não é etapa julgada, etapa SRV-DOSSIE ou entrada externa (MAT-05).","Ciclo, dependência inexistente, relatório que não é a última etapa, cálculo como entrada do convite (MAT-15, MAT-16) ou orçamento que não cabe."]},"ordem_de_ativacao":{"ate_ligar":"Pedido de serviço de agente ainda não ligado vai para o destino_fora_da_v2 (v1).","ligados_desde_o_inicio":["HELENA","CAIO","CLARA","ISABELA"],"ligar_um_passo":"No passo, o agente passa a ''ligado'': os serviços dele podem ser publicados e as aptidões de revisão dele podem ser ligadas (teste 9 + seu toque). O revisor titular de cada serviço do agente já está ligado e APTO no tipo antes de o serviço ir a ESTAGIO.","passos":[{"agente":"RAVI","fase":"fase 3","passo":1,"quando":"No primeiro roteiro que pedir pesquisa (você decide). No mais tardar, como primeiro passo da fase 4."},{"agente":"LAURA","fase":"fase 4","passo":2},{"agente":"AUGUSTO","fase":"fase 4","passo":3},{"agente":"DANIEL","fase":"fase 4","passo":4},{"agente":"MARINA","fase":"fase 4","passo":5},{"agente":"OLIVIA","fase":"fase 4","passo":6},{"agente":"FELIPE","fase":"fase 4","passo":7},{"agente":"BIANCA","fase":"fase 4","passo":8},{"agente":"CAMILA","fase":"fase 4","passo":9},{"agente":"VICTOR","fase":"fase 4","passo":10},{"agente":"PEDRO","fase":"fase 4","passo":11},{"agente":"RENATA","fase":"fase 4","passo":12},{"agente":"JOANA","fase":"fase 4","passo":13},{"agente":"NINA","fase":"fase 4","passo":14},{"agente":"MAYA","fase":"fase 4","passo":15},{"agente":"THEO","fase":"fase 4","passo":16},{"agente":"BRUNO","fase":"fase 4","passo":17}]},"pedidos_de_fronteira":[{"certo":"SRV-CALCULO","pedido":"Monta o fluxo de caixa dos próximos 3 meses com estes números."},{"certo":"SRV-CONTROLE-ADMINISTRATIVO","pedido":"Quais contratos e boletos vencem nos próximos 60 dias e o que cada um exige?"},{"certo":"SRV-ANALISE-DE-DADOS","pedido":"Classifica estas 20 reclamações por motivo e conta quantas se repetem."},{"certo":"SRV-RASCUNHO-DE-RESPOSTA","pedido":"Um cliente reclamou da fatura: o que eu respondo para ele?"},{"certo":"SRV-ROTEIRO-TREINAMENTO","pedido":"Ensina o participante a gravar sem ser reprovado."},{"certo":"SRV-PROCEDIMENTO-OPERACIONAL","pedido":"Como a minha equipe confere as horas dos participantes toda semana?"},{"certo":"SRV-PLANO-DE-CAMPANHA","pedido":"Qual canal testar para achar participantes e como medir?"},{"certo":"SRV-COPY","pedido":"Escreve o texto do anúncio da campanha que eu aprovei."},{"certo":"SRV-ROTEIRO-COMERCIAL","pedido":"Como abordar um síndico, um por um?"},{"certo":"SRV-PLANO-DE-PROJETO","pedido":"O que eu faço em cada semana até o lançamento?"},{"certo":"SRV-ANALISE-ESTRATEGICA","pedido":"Vale mais vender para residências ou para empresas?"},{"certo":"SRV-REQUISITOS-DE-PRODUTO","pedido":"O que construir primeiro no app?"},{"certo":"SRV-DOSSIE","pedido":"O que a página de termos da Mimix diz sobre indicação?"},{"certo":"SRV-PLANO-DE-SUCESSO","pedido":"Quais clientes estão em risco de cancelar?"},{"certo":"SRV-PLANO-DE-PRATICA","pedido":"Quero treinar falar em público sem travar."},{"certo":"FORA-CONTRATOS-E-PRIVACIDADE","pedido":"Este contrato de fornecedor tem alguma cláusula perigosa?"},{"certo":"FORA-FISCAL-CONTABIL","pedido":"Quanto imposto a empresa paga neste mês?"},{"certo":"FORA-PACOTE-DE-VOZ","pedido":"Escreve a voz e as palavras proibidas da iGreen."}],"portao1_comum":[{"descricao":"Todas as seções obrigatórias do tipo, no formato de campo do tipo.","fase":"fase 1","fecha_furos":["K-13","A-17"],"gravidade":"RECUSA","id":"CHK-COMUM-01"},{"descricao":"Dentro do limite de caracteres do tipo.","fase":"fase 1","fecha_furos":["CONF-21"],"gravidade":"RECUSA","id":"CHK-COMUM-02"},{"descricao":"Texto em português (citação original pode estar em outra língua, com a tradução em campo à parte).","fase":"fase 1","fecha_furos":["CONF-21"],"gravidade":"RECUSA","id":"CHK-COMUM-03"},{"descricao":"Texto puro: sem HTML, código de página, imagem ou caractere invisível.","fase":"fase 1","fecha_furos":["M-13","B-9"],"gravidade":"RECUSA","id":"CHK-COMUM-04"},{"descricao":"Nenhuma frase dizendo que o agente agiu fora (''enviei'', ''cadastrei'', ''publiquei'', ''paguei'', ''liguei'', ''assinei'' e parecidas).","fase":"fase 1","fecha_furos":["CONF-20","B-17"],"gravidade":"RECUSA","id":"CHK-COMUM-05"},{"descricao":"Toda afirmação com fonte traz citação: trecho contínuo de 12 palavras ou mais (ou frase inteira) de página lida NESTA execução pela nossa ferramenta, ou de fonte importada que veio no pacote; tradução só em campo à parte.","fase":"fase 2","fecha_furos":["C-8","K-1","M-15"],"gravidade":"RECUSA","id":"CHK-COMUM-06"},{"descricao":"Link só de página lida na tarefa; qualquer outro chega marcado ''link não conferido''.","fase":"fase 2","fecha_furos":["C-7","B-9"],"gravidade":"MARCA","id":"CHK-COMUM-07"},{"descricao":"Confiança declarada pela IA chega marcada ''autoavaliação da IA'' e nunca entra na faixa.","fase":"fase 2","fecha_furos":["C-13"],"gravidade":"MARCA","id":"CHK-COMUM-08"},{"descricao":"Grafia oficial da marca: eLiving™ (nunca ''E-living'', ''Eliving'', ''E-Living'' ou ''Iliving'').","fase":"fase 1","fecha_furos":["DEC-023"],"gravidade":"RECUSA","id":"CHK-COMUM-09"},{"descricao":"Ação externa da entrega: tipo dentro de acao_externa_permitida do serviço da etapa; com SO_FUNDADOR, o id está em acoes_do_fundador do serviço e é exatamente a ação que o plano deu àquela etapa (no avulso, a única do serviço). Nenhum texto livre da IA sobre a ação.","fase":"fase 1","fecha_furos":["CONF-20","B-17","MAQ-08"],"gravidade":"RECUSA","id":"CHK-COMUM-10"}],"recebem_card":["ESTAGIO","ATIVO"],"regra_do_relatorio_final":"O relatório final junta entregas de vários autores, e quem o revisa pode ter feito uma delas (o Caio fez o cálculo; a Clara, reserva, fez o parecer). Por isso quem revisa o relatório: (1) confere SÓ a fidelidade às entregas aprovadas — cada frase escrita pela Helena diz o mesmo que a entrega aprovada que ela cita, nenhum risco ou pergunta foi escondido ou suavizado, a ordem das dependências foi respeitada — e a linguagem — simples, sem códigos internos; (2) NUNCA reavalia o mérito de nenhuma entrega, inclusive a própria: entrega aprovada não volta a ser julgada no relatório; (3) revisa sem internet; (4) nunca é a autora do relatório (Helena). A parte montada pelo código (entregas aprovadas, números, riscos, perguntas, fontes, as ações do fundador das etapas aprovadas e os passos fixos do roteiro) não é reescrita por ninguém.","regras_da_matriz":[{"id":"MAT-01","regra":"Cada um dos 21 agentes de vocabulario.identidades.agentes é dono de pelo menos 1 serviço, e esse serviço é só dele."},{"id":"MAT-02","regra":"Todo serviço tem exatamente 1 dono e 1 tipo de entrega; todo tipo de entrega pertence a exatamente 1 serviço (e portanto a 1 dono). Não existe autor reserva: com o serviço pausado, a etapa espera na fila com motivo CAPACIDADE (classe AGENTE_PAUSADO), com aviso em 1 hora e cartão em 6 horas, onde você religa o serviço e escolhe ESPERAR, ou cancela."},{"id":"MAT-03","regra":"Revisor ≠ dono. Reserva ≠ dono e ≠ revisor. O revisor é um dos 21 agentes; a reserva é um dos 21 ou FUNDADOR. Você é sempre a última reserva (passagens.yaml, designacao_de_revisor.ultima_reserva), mesmo quando não está escrito."},{"id":"MAT-04","regra":"Revisor e reserva (quando agentes) têm o tipo em ''revisa'', com a aptidão do par. E ''revisa'' de cada agente lista só os tipos em que ele é revisor ou reserva: capacidade declarada é capacidade usada."},{"id":"MAT-05","regra":"Regra 4 (julgar depois): para todo tipo de julga_tipos, o revisor e a reserva desse tipo não são o dono da julgadora nem o revisor ou a reserva dela. Como o dossiê está em julga_tipos, a base de fato do parecer também nunca é revisada por quem julga (furo 18). E a etapa SRV-PARECER só recebe como entrada etapas que ela julga, etapas SRV-DOSSIE e entradas externas: nenhuma peça revisada pela cadeia do parecer entra nele."},{"id":"MAT-06","regra":"O dono de um tipo que a julgadora julga não é revisor nem reserva da julgadora: ninguém aprova o parecer sobre a própria peça."},{"id":"MAT-07","regra":"A julgadora (só o SRV-PARECER) nunca é card sozinho (escolhivel e avulso false): entra num roteiro ou no grafo fixo do serviço sempre julgado (montagem_do_plano). Julga pelo menos uma etapa, só de tipos de julga_tipos, depende das etapas que julga e tem você como segundo revisor obrigatório (passagens.yaml E74 e E81-E83): o parecer só vale com o seu Aprovar."},{"id":"MAT-08","regra":"Ninguém é revisor titular de mais de 3 tipos, e em nenhum passo da ordem_de_ativacao alguém é o primeiro revisor efetivo de mais de 3 tipos publicados. A Helena não é revisora universal: como revisa o parecer, pela MAT-05 ela não revisa nenhum tipo que o parecer julga."},{"id":"MAT-09","regra":"Serviço com ferramenta (usa_internet: true) só libera ENTREGAR e REGISTRAR_FALHA, e só acao_externa NENHUMA: texto de página lida nunca vira pergunta para você, pedido a outro agente nem proposta na sua lista (C-7, MEL-27). Ferramentas: só ler_pagina e buscar, efeito LER, cada uma a partir da fase dela e com o acesso_sem_efeito (MEL-34)."},{"id":"MAT-10","regra":"Toda revisão roda sem ferramenta (servidor vazio) e com o apelido revisao-padrao (models.yaml). O revisor recebe do código o parágrafo em volta de cada citação; ele não lê a internet (MEL-30, C-7)."},{"id":"MAT-11","regra":"Efeito de todo serviço: interno. O que é externo só existe como ação do fundador da lista fechada do serviço: no máximo 1 por serviço, com no máximo 2 categorias e descrição fixa. A entrega só diz SO_FUNDADOR ou NENHUMA e o id da ação (checagem CHK-COMUM-10); o texto que você vê vem da descrição fixa e do roteiro, nunca da IA. Nasce quando o card fica PRONTO (passagens.yaml E110), no máximo uma por etapa, e é feita por você. PELO_MOTOR não está liberado para nenhum serviço (exige executor próprio, teste e decisão sua, na fase 4 ou depois). O relatório final não tem ação do fundador."},{"id":"MAT-12","regra":"Um serviço só vai a ESTAGIO com o dono ligado e o revisor titular ligado e APTO no tipo (o titular é sempre de passo igual ou anterior ao do dono na ordem_de_ativacao). O titular é fixo: trocá-lo é versão nova do serviço, com o teste 9 do par novo e o seu toque (furos 10 e 24). A reserva só entra na lista efetiva quando a aptidão dela fica APTA (teste 9 + seu toque), e nunca muda o titular. Sem nenhum revisor de IA apto, o serviço desce para PAUSADO."},{"id":"MAT-13","regra":"Estados separados: serviço (papel AUTOR), aptidão de revisão (por agente e tipo) e coordenação (Helena). O disjuntor só pausa serviço. O estado do agente no organograma é um resumo para a tela, derivado dos serviços (ATIVO se algum ATIVO; ESTAGIO se algum ESTAGIO; senão PAUSADO), e nunca é usado para designar. A fase do agente é a primeira fase entre os serviços dele."},{"id":"MAT-14","regra":"Escopo PESSOAL: só os serviços da Laura têm a empresa PESSOAL, e eles não têm nenhuma outra. Card PESSOAL nunca recebe pacote de empresa, só passa pela Laura, pela Helena (dona do card e revisora) e por você, e nunca entra em roteiro com etapa de empresa."},{"id":"MAT-15","regra":"Relatório final: exatamente um serviço (dono HELENA), nunca avulso, sempre a última etapa do roteiro, dependendo de todas as outras, nunca pulado, sem ação do fundador; a revisora nunca é a Helena e segue a regra_do_relatorio_final."},{"id":"MAT-16","regra":"Nenhum roteiro dá a saída do SRV-CALCULO como entrada do SRV-COPY: o convite nem recebe os números (C-11)."},{"id":"MAT-17","regra":"Toda lista de ações tem ENTREGAR e REGISTRAR_FALHA e só usa nomes de acoes_do_autor_liberaveis; PEDIR_SUBCARD não aparece (MEL-24)."},{"id":"MAT-18","regra":"Sirlene, Doutor Vital, Alex e Rafael são personagens do produto eLiving™, nunca dono, revisor ou reserva de serviço."},{"id":"MAT-19","regra":"Escolhível implica avulso (o código sabe montar o plano dele sozinho). Serviço escolhível tem de 3 a 5 exemplos de pedido, sem repetir exemplo de outro serviço; serviço não escolhível não tem exemplos. Cada pedido_de_fronteira aponta para exatamente 1 destino que existe, e nenhum serviço manda para si mesmo no ''nao_atende''."},{"id":"MAT-20","regra":"Nenhum serviço muda prioridade ou prazo: só você muda (regra 7). A sugestão de prazo da Helena vira item na sua lista."},{"id":"MAT-21","regra":"Revisores efetivos: só agente com aptidão APTA no tipo, mais FUNDADOR no fim, calculados ao montar o plano e gravados no card (bloco revisores_efetivos). Falta de vaga nunca troca revisor."},{"id":"MAT-22","regra":"Sempre julgado: todo serviço com ação do fundador tem o tipo em julga_tipos (julgado_pelo_parecer: SEMPRE), e toda etapa dele, em qualquer plano (roteiro ou grafo do avulso), é julgada por uma etapa SRV-PARECER do mesmo card. Por isso a ação dele só nasce com o parecer aprovado por você no mesmo card (o card só fica PRONTO assim). Tipo de julga_tipos sem ação do fundador é julgado só quando o roteiro pede (SE_O_ROTEIRO_PEDIR); sem parecer, a faixa do card mostra ''sem conferência jurídica''."},{"id":"MAT-23","regra":"Empresa: serviço em ESTAGIO ou ATIVO só lista empresa com pacote CONFIRMADO (organograma.yaml). O validador do plano recusa card cuja empresa não está em todos os serviços do plano ou cujo pacote não está CONFIRMADO, com o motivo à vista."},{"id":"MAT-24","regra":"Toda área do mapa_de_areas aponta para exatamente 1 serviço ou para 1 item de fora_do_catalogo com destino, dono e prazo."},{"id":"MAT-25","regra":"MODELO_MENOR (sua resposta no cartão de cota) vale só para a execução do AUTOR, só na classe COTA, só em serviço com modelo_menor APTO (bateria 3 de 3 no modelo menor), nunca no SRV-PARECER nem no SRV-RELATORIO-FINAL. Fora disso o cartão não oferece, e se chegar o motor trata como ESPERAR (mesma passagem E88). Revisão e Helena rodam sempre no apelido."},{"id":"MAT-26","regra":"Conflito da Helena: quando a Helena é autora ou revisora designada da etapa em resolução, o motor não pede RECOMENDAR; o relógio leva a etapa a você na hora (E101), sem recomendação, com a marca ''a Helena participou desta peça''."}],"revisores_efetivos":{"congelada":"A lista não muda durante a vida do card, nem quando o motor designa de novo depois de uma rodada nova. Uma aptidão pausada depois vale só para planos novos (descer nunca mexe em card em andamento).","disponivel_quer_dizer":"Na lista efetiva. Falta de vaga NUNCA troca o revisor: a revisão espera a vaga do designado (fila por prioridade e chegada); o atraso aparece nos avisos do prazo do card.","regra":"Ao montar o plano (estado VALIDANDO_PLANO do card), o código calcula, para cada etapa, a lista [revisor, reserva] do serviço, tira dela todo agente cuja aptidão no tipo não esteja APTA e põe FUNDADOR no fim. A lista é gravada no plano do card (card.schema.json, plano.etapas[].revisores) e é ela, e não a do catálogo, que vai para o roteiro da máquina (campo ''revisores''). A máquina ainda tira o autor e quem julga a peça depois (passagens.yaml, designacao_de_revisor).","sem_capacidade_na_revisao":"Na etapa em REVISAO, o motor só manda SEM_CAPACIDADE com classe COTA, LOGIN ou BANCO. Nunca AGENTE_PAUSADO: aptidão pausada não tira revisão já designada. (Guarda a acrescentar na tabela pela etapa da máquina; ver pendências.)","sem_revisor_de_ia":"Se a lista efetiva de uma etapa ficar só com FUNDADOR, o validador do plano recusa (PLANO_INVALIDO): nenhum serviço roda na v2 com você como único revisor."},"servicos":[{"acao_externa_permitida":["NENHUMA"],"acoes_do_fundador":[],"acoes_permitidas":["ENTREGAR","REGISTRAR_FALHA"],"avulso":false,"dono":"HELENA","efeito":"interno","empresas":["BIZ-003","BIZ-004"],"entrega":"deliverables/relatorio_final.yaml","escolhivel":false,"estado":"ESTAGIO","exemplos_de_pedido":[],"fase_de_ativacao":"v2.0","ferramentas":[],"id":"SRV-RELATORIO-FINAL","julgado_pelo_parecer":"NUNCA","modelo_menor":"NUNCA","nao_atende":["Pedido direto: o relatório só existe como última etapa de um roteiro.","Rever o mérito das entregas: isso já foi feito na revisão de cada uma.","Propor ação externa: a lista do que só você faz é montada pelo código com as ações das etapas aprovadas e os passos fixos do roteiro."],"nome":"Relatório final do card","pode_entrar_em_roteiro":true,"pode_ser_pulada":false,"pronto_padrao":"Parte montada pelo código (entregas aprovadas, números, riscos, perguntas, fontes, as ações do fundador das etapas aprovadas e os passos fixos do roteiro) e, escrito pela Helena, um resumo de 5 linhas e os próximos passos, cada frase ligada a uma entrega aprovada.","regra_do_revisor":"regra_do_relatorio_final","reserva":"CLARA","revisor":"CAIO","tipo_de_entrega":"relatorio_final","usa_internet":false},{"acao_externa_permitida":["NENHUMA"],"acoes_do_fundador":[],"acoes_permitidas":["ENTREGAR","PERGUNTAR","DEVOLVER_A_QUEM_PEDIU","REGISTRAR_FALHA"],"avulso":true,"dono":"LAURA","efeito":"interno","empresas":["PESSOAL"],"entrega":"deliverables/plano_de_pratica.yaml","escolhivel":true,"estado":"RASCUNHO","exemplos_de_pedido":["Quero explicar meu projeto em 1 minuto sem rodeio; segue a transcrição da minha última tentativa.","Me ajuda a responder críticas sem ficar na defensiva; aqui está a última conversa.","Quero praticar pedir as coisas de forma mais direta nas reuniões."],"fase_de_ativacao":"fase 4","ferramentas":[],"id":"SRV-PLANO-DE-PRATICA","julgado_pelo_parecer":"NUNCA","modelo_menor":"SEM_PROVA","nao_atende":["Assunto de empresa: vai para o serviço da área.","Diagnóstico clínico ou psicológico.","Funções, vagas e desempenho de pessoas das empresas: SRV-PERFIL-DE-FUNCAO (Bianca)."],"nome":"Prática de comunicação do fundador","pode_entrar_em_roteiro":false,"pode_ser_pulada":false,"pronto_padrao":"Até 2 padrões, cada um com trecho do seu material; 1 exercício curto com critério para praticar; registro comparável da evolução e a próxima prática.","reserva":"FUNDADOR","revisor":"HELENA","tipo_de_entrega":"plano_de_pratica","usa_internet":false},{"acao_externa_permitida":["NENHUMA"],"acoes_do_fundador":[],"acoes_permitidas":["ENTREGAR","PERGUNTAR","DEVOLVER_A_QUEM_PEDIU","REGISTRAR_FALHA"],"avulso":true,"dono":"AUGUSTO","efeito":"interno","empresas":["BIZ-001","BIZ-002","BIZ-003","BIZ-004"],"entrega":"deliverables/analise_estrategica.yaml","escolhivel":true,"estado":"RASCUNHO","exemplos_de_pedido":["Vale mais focar a iGreen em residências ou em pequenas empresas nos próximos 6 meses?","Quais são 3 caminhos para a Humano Digital crescer sem contratar ninguém?","Lanço a eLiving™ primeiro só no Brasil ou já em inglês?"],"fase_de_ativacao":"fase 4","ferramentas":[],"id":"SRV-ANALISE-ESTRATEGICA","julgado_pelo_parecer":"NUNCA","modelo_menor":"SEM_PROVA","nao_atende":["Plano de campanha e canais: SRV-PLANO-DE-CAMPANHA (Camila).","O que construir no produto: SRV-REQUISITOS-DE-PRODUTO (Nina).","Conta detalhada: SRV-CALCULO (Caio).","Decidir no seu lugar: a escolha é sua."],"nome":"Análise de opções estratégicas","pode_entrar_em_roteiro":true,"pode_ser_pulada":true,"pronto_padrao":"Duas ou mais opções comparadas pelos mesmos critérios, premissas marcadas (dado, estimativa ou hipótese), recomendação condicionada às provas e plano de validação com indicador e decisão.","reserva":"CAIO","revisor":"RAVI","tipo_de_entrega":"analise_estrategica","usa_internet":false},{"acao_externa_permitida":["NENHUMA"],"acoes_do_fundador":[],"acoes_permitidas":["ENTREGAR","PERGUNTAR","DEVOLVER_A_QUEM_PEDIU","REGISTRAR_FALHA"],"avulso":true,"dono":"MARINA","efeito":"interno","empresas":["BIZ-001","BIZ-002","BIZ-003","BIZ-004"],"entrega":"deliverables/plano_de_projeto.yaml","escolhivel":true,"estado":"RASCUNHO","exemplos_de_pedido":["Monta o cronograma do lançamento do site da iGreen, com o que eu faço em cada semana.","Quero um plano de 30 dias para abrir a conta PJ e organizar os contratos.","Organiza em marcos e datas o que falta para a eLiving™ ter a primeira versão do app."],"fase_de_ativacao":"fase 4","ferramentas":[],"id":"SRV-PLANO-DE-PROJETO","julgado_pelo_parecer":"NUNCA","modelo_menor":"SEM_PROVA","nao_atende":["Acompanhar, mover ou cobrar cards e etapas dos agentes: é o motor (FORA-COORDENACAO).","Escolher a fila ou a prioridade: é sua.","Rotina recorrente da operação: SRV-PROCEDIMENTO-OPERACIONAL (Olívia).","Documentos e vencimentos: SRV-CONTROLE-ADMINISTRATIVO (Felipe)."],"nome":"Plano de projeto e cronograma para você","pode_entrar_em_roteiro":true,"pode_ser_pulada":true,"pronto_padrao":"Marcos com data e hora de Brasília, dono humano de cada marco (você ou quem você indicar), dependências, o pronto de cada marco e o primeiro passo.","reserva":"FELIPE","revisor":"AUGUSTO","tipo_de_entrega":"plano_de_projeto","usa_internet":false},{"acao_externa_permitida":["NENHUMA"],"acoes_do_fundador":[],"acoes_permitidas":["ENTREGAR","PERGUNTAR","DEVOLVER_A_QUEM_PEDIU","REGISTRAR_FALHA"],"avulso":true,"dono":"CAIO","efeito":"interno","empresas":["BIZ-003","BIZ-004"],"entrega":"deliverables/calculo.yaml","escolhivel":true,"estado":"ESTAGIO","exemplos_de_pedido":["Quanto entra por mês com 10 pessoas gravando 5 horas por semana a US$ 0,50 a hora?","Qual o ponto de equilíbrio da eLiving™ com assinatura de R$ 29 por mês?","Monta a projeção de caixa da Humano Digital para os próximos 3 meses com estes números."],"fase_de_ativacao":"v2.0","ferramentas":[],"id":"SRV-CALCULO","julgado_pelo_parecer":"NUNCA","modelo_menor":"SEM_PROVA","nao_atende":["Pagar, transferir ou lançar no financeiro: ação sua.","Agenda de vencimentos, contratos e boletos: SRV-CONTROLE-ADMINISTRATIVO (Felipe).","Imposto, nota fiscal e fechamento contábil: FORA-FISCAL-CONTABIL.","Indicador que não é dinheiro: SRV-ANALISE-DE-DADOS (Daniel).","Escolher entre estratégias: SRV-ANALISE-ESTRATEGICA (Augusto)."],"nome":"Conta e cenários financeiros","pode_entrar_em_roteiro":true,"pode_ser_pulada":true,"pronto_padrao":"Modelo com entradas (cada uma com origem: dado seu, fonte com data ou premissa marcada), fórmulas que o código refaz, 3 cenários e os riscos dos números; previsão nunca aparece como caixa.","reserva":"CLARA","revisor":"HELENA","tipo_de_entrega":"calculo","usa_internet":false},{"acao_externa_permitida":["NENHUMA"],"acoes_do_fundador":[],"acoes_permitidas":["ENTREGAR","PERGUNTAR","DEVOLVER_A_QUEM_PEDIU","REGISTRAR_FALHA"],"avulso":true,"dono":"DANIEL","efeito":"interno","empresas":["BIZ-001","BIZ-002","BIZ-003","BIZ-004"],"entrega":"deliverables/analise_de_dados.yaml","escolhivel":true,"estado":"RASCUNHO","exemplos_de_pedido":["Qual foi a taxa de conversão do funil da iGreen em setembro, com estes dados?","Define o indicador de engajamento semanal da eLiving™ e como medir.","Estes números do atendimento mostram aumento de reclamação?","Quantos pacientes voltaram para a segunda consulta no Ecossistema de Saúde, com esta planilha?"],"fase_de_ativacao":"fase 4","ferramentas":[],"id":"SRV-ANALISE-DE-DADOS","julgado_pelo_parecer":"NUNCA","modelo_menor":"SEM_PROVA","nao_atende":["Conta de dinheiro: SRV-CALCULO (Caio).","Responder uma solicitação de cliente: SRV-RASCUNHO-DE-RESPOSTA (Joana).","Coletar dado de pessoa ou de sistema: você fornece os dados.","Mudar o app para medir: SRV-PROPOSTA-TECNICA (Theo)."],"nome":"Indicador e leitura de dados","pode_entrar_em_roteiro":true,"pode_ser_pulada":true,"pronto_padrao":"Indicador com fórmula, unidade, janela e fonte; leitura que responde à pergunta; denominador, duplicatas e ausências conferidos (ausência não é zero); lacunas e próximo passo de medição.","reserva":"CAIO","revisor":"RAVI","tipo_de_entrega":"analise_de_dados","usa_internet":false},{"acao_externa_permitida":["NENHUMA","SO_FUNDADOR"],"acoes_do_fundador":[{"categorias":["GASTO","CONTRATO"],"descricao":"Pagar, renovar ou assinar o que vence, conforme a agenda aprovada e o parecer aprovado.","id":"AF-ADMIN-PAGAR-RENOVAR-ASSINAR"}],"acoes_permitidas":["ENTREGAR","PERGUNTAR","DEVOLVER_A_QUEM_PEDIU","REGISTRAR_FALHA"],"avulso":true,"dono":"FELIPE","efeito":"interno","empresas":["BIZ-001","BIZ-002","BIZ-003","BIZ-004"],"entrega":"deliverables/controle_administrativo.yaml","escolhivel":true,"estado":"RASCUNHO","exemplos_de_pedido":["Que documentos e prazos vencem nos próximos 60 dias, com estes contratos?","Organiza os documentos da Humano Digital com o dono e onde está cada um.","Lista os fornecedores da iGreen e o que falta de cada um."],"fase_de_ativacao":"fase 4","ferramentas":[],"id":"SRV-CONTROLE-ADMINISTRATIVO","julgado_pelo_parecer":"SEMPRE","modelo_menor":"SEM_PROVA","nao_atende":["Pagar, assinar, contratar ou renovar: ação sua.","Valores, saldo e projeção de caixa: SRV-CALCULO (Caio).","Alterar documento original.","Dizer se uma cláusula é arriscada: FORA-CONTRATOS-E-PRIVACIDADE (o parecer do card julga só a agenda e a ação proposta).","Como a rotina da operação funciona: SRV-PROCEDIMENTO-OPERACIONAL (Olívia)."],"nome":"Controle de documentos, fornecedores e vencimentos","pode_entrar_em_roteiro":true,"pode_ser_pulada":false,"pronto_padrao":"Cada registro com tipo, fonte, dono e onde está; agenda de vencimentos com antecedência e a ação necessária; documento recebido separado de obrigação conferida.","reserva":"MARINA","revisor":"OLIVIA","tipo_de_entrega":"controle_administrativo","usa_internet":false},{"acao_externa_permitida":["NENHUMA"],"acoes_do_fundador":[],"acoes_permitidas":["ENTREGAR","REGISTRAR_FALHA"],"avulso":false,"dono":"CLARA","efeito":"interno","empresas":["BIZ-003","BIZ-004"],"entrega":"deliverables/parecer.yaml","escolhivel":false,"estado":"ESTAGIO","exemplos_de_pedido":[],"fase_de_ativacao":"v2.0","ferramentas":[{"desde":"fase 3","efeito":"LER","nome